#include "kernel_operator.h"

class KernelCoTAttention {
public:
    __aicore__ inline KernelCoTAttention() {}

    __aicore__ inline void Init(GM_ADDR k1, GM_ADDR att, GM_ADDR v, GM_ADDR y,
                               uint32_t bs, uint32_t C, uint32_t H, uint32_t W,
                               uint32_t hw, uint32_t totalRows)
    {
        this->bs = bs;
        this->C = C;
        this->H = H;
        this->W = W;
        this->hw = hw;
        this->totalRows = totalRows;
        this->ubStride = ((hw + 7U) / 8U) * 8U;

        const uint64_t tensorSize = static_cast<uint64_t>(totalRows) * static_cast<uint64_t>(hw);
        k1Gm.SetGlobalBuffer((__gm__ float*)k1, tensorSize);
        attGm.SetGlobalBuffer((__gm__ float*)att, tensorSize);
        vGm.SetGlobalBuffer((__gm__ float*)v, tensorSize);
        yGm.SetGlobalBuffer((__gm__ float*)y, tensorSize);

        const uint32_t storageBytes = this->ubStride * static_cast<uint32_t>(sizeof(float));
        pipe.InitBuffer(attQueue, 1, storageBytes);
        pipe.InitBuffer(vQueue, 1, storageBytes);
        pipe.InitBuffer(k1Queue, 1, storageBytes);
        pipe.InitBuffer(outQueue, 1, storageBytes);
        pipe.InitBuffer(tmpBuf, storageBytes);
        pipe.InitBuffer(reduceResultBuf, 2U * 32U);
        pipe.InitBuffer(reduceWorkspaceBuf, 256U);
    }

    __aicore__ inline void Process()
    {
        const uint32_t coreId = static_cast<uint32_t>(AscendC::GetBlockIdx());
        const uint32_t coreNum = static_cast<uint32_t>(AscendC::GetBlockNum());
        if (coreNum == 0U || coreId >= coreNum) return;

        const uint32_t startRow = static_cast<uint32_t>(
            (static_cast<uint64_t>(coreId) * this->totalRows) / coreNum);
        const uint32_t endRow = static_cast<uint32_t>(
            (static_cast<uint64_t>(coreId + 1U) * this->totalRows) / coreNum);
        for (uint32_t row = startRow; row < endRow; ++row) {
            Compute1Row(row);
        }
    }

private:
    __aicore__ inline void SoftmaxMulAddOneRow(uint32_t row,
                                              AscendC::LocalTensor<float>& attL,
                                              AscendC::LocalTensor<float>& vL,
                                              AscendC::LocalTensor<float>& k1L,
                                              AscendC::LocalTensor<float>& tmpL,
                                              AscendC::LocalTensor<float>& outL)
    {
        AscendC::LocalTensor<float> reduceResult = reduceResultBuf.Get<float>();
        AscendC::LocalTensor<float> maxResult = reduceResult;
        AscendC::LocalTensor<float> sumResult = reduceResult[8];
        AscendC::LocalTensor<float> reduceWorkspace = reduceWorkspaceBuf.Get<float>();

        AscendC::ReduceMax(maxResult, attL, reduceWorkspace, static_cast<int32_t>(this->hw), false);
        const auto eventVToS = pipe.FetchEventID<AscendC::HardEvent::V_S>();
        AscendC::SetFlag<AscendC::HardEvent::V_S>(eventVToS);
        AscendC::WaitFlag<AscendC::HardEvent::V_S>(eventVToS);
        const float maxVal = maxResult.GetValue(0);

        AscendC::Adds(tmpL, attL, -maxVal, static_cast<int32_t>(this->hw));
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Exp(tmpL, tmpL, static_cast<int32_t>(this->hw));
        AscendC::PipeBarrier<PIPE_V>();

        AscendC::ReduceSum(sumResult, tmpL, reduceWorkspace, static_cast<int32_t>(this->hw));
        AscendC::SetFlag<AscendC::HardEvent::V_S>(eventVToS);
        AscendC::WaitFlag<AscendC::HardEvent::V_S>(eventVToS);
        const float sumExp = sumResult.GetValue(0);
        const float invSum = 1.0f / (sumExp > 0.0f ? sumExp : 1.0f);

        AscendC::Muls(tmpL, tmpL, invSum, static_cast<int32_t>(this->hw));
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Mul(outL, tmpL, vL, static_cast<int32_t>(this->hw));
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Add(outL, k1L, outL, static_cast<int32_t>(this->hw));
    }

    __aicore__ inline void Compute1Row(uint32_t row)
    {
        const uint64_t rowOff = static_cast<uint64_t>(row) * static_cast<uint64_t>(this->hw);
        const uint32_t rowBytes = this->hw * static_cast<uint32_t>(sizeof(float));
        const AscendC::DataCopyExtParams copyParams{1U, rowBytes, 0U, 0U, 0U};
        const AscendC::DataCopyPadExtParams<float> noPad{false, 0U, 0U, 0.0f};

        AscendC::LocalTensor<float> attIn = attQueue.AllocTensor<float>();
        AscendC::LocalTensor<float> vIn = vQueue.AllocTensor<float>();
        AscendC::LocalTensor<float> k1In = k1Queue.AllocTensor<float>();
        AscendC::DataCopyPad(attIn, attGm[rowOff], copyParams, noPad);
        AscendC::DataCopyPad(vIn, vGm[rowOff], copyParams, noPad);
        AscendC::DataCopyPad(k1In, k1Gm[rowOff], copyParams, noPad);
        attQueue.EnQue(attIn);
        vQueue.EnQue(vIn);
        k1Queue.EnQue(k1In);

        AscendC::LocalTensor<float> attL = attQueue.DeQue<float>();
        AscendC::LocalTensor<float> vL = vQueue.DeQue<float>();
        AscendC::LocalTensor<float> k1L = k1Queue.DeQue<float>();
        AscendC::LocalTensor<float> tmpL = tmpBuf.Get<float>();
        AscendC::LocalTensor<float> outL = outQueue.AllocTensor<float>();

        SoftmaxMulAddOneRow(row, attL, vL, k1L, tmpL, outL);
        outQueue.EnQue(outL);
        AscendC::LocalTensor<float> out = outQueue.DeQue<float>();
        AscendC::DataCopyPad(yGm[rowOff], out, copyParams);

        outQueue.FreeTensor(out);
        attQueue.FreeTensor(attL);
        vQueue.FreeTensor(vL);
        k1Queue.FreeTensor(k1L);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> attQueue;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> vQueue;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> k1Queue;
    AscendC::TQue<AscendC::TPosition::VECOUT, 1> outQueue;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf;
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceResultBuf;
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceWorkspaceBuf;

    AscendC::GlobalTensor<float> k1Gm;
    AscendC::GlobalTensor<float> attGm;
    AscendC::GlobalTensor<float> vGm;
    AscendC::GlobalTensor<float> yGm;

    uint32_t bs {0}, C {0}, H {0}, W {0}, hw {0};
    uint32_t totalRows {0};
    uint32_t ubStride {0};
};

extern "C" __global__ __aicore__ void co_t_attention_custom(GM_ADDR k1, GM_ADDR att, GM_ADDR v, GM_ADDR y,
                                                           GM_ADDR workspace, GM_ADDR tiling)
{
