#include "kernel_operator.h"

class KernelDAModuleCustom {
public:
    __aicore__ inline KernelDAModuleCustom() {}

    __aicore__ inline void Init(GM_ADDR p_out, GM_ADDR c_out, GM_ADDR y,
                               uint32_t bs, uint32_t c, uint32_t hw,
                               uint32_t totalTasks, uint32_t rowValid,
                               uint32_t rowStorage)
    {
        this->bs = bs;
        this->c = c;
        this->hw = hw;
        this->totalTasks = totalTasks;
        this->rowValid = rowValid;
        this->rowStorage = rowStorage;

        const uint64_t totalP = (uint64_t)bs * (uint64_t)hw * (uint64_t)c;
        const uint64_t totalC = (uint64_t)bs * (uint64_t)c  * (uint64_t)hw;

        pGm.SetGlobalBuffer((__gm__ float*)p_out, totalP); // [bs, hw, c]
        cGm.SetGlobalBuffer((__gm__ float*)c_out, totalC); // [bs, c, hw]
        yGm.SetGlobalBuffer((__gm__ float*)y,     totalC); // write as flat [bs, c, hw] (matches contiguous NCHW storage)

        const uint32_t rowBytes = rowStorage * static_cast<uint32_t>(sizeof(float));
        pipe.InitBuffer(pSegBuf, rowBytes);
        pipe.InitBuffer(cRowQueue, 1, rowBytes);
        pipe.InitBuffer(outRowQueue, 1, rowBytes);
    }

    __aicore__ inline void Process()
    {
        const uint32_t core = (uint32_t)AscendC::GetBlockIdx();
        const uint32_t blockCount = static_cast<uint32_t>(AscendC::GetBlockNum());
        const uint32_t rowBytes = rowValid * static_cast<uint32_t>(sizeof(float));
        const AscendC::DataCopyExtParams copyParams{
            static_cast<uint16_t>(1), rowBytes, static_cast<uint32_t>(0), static_cast<uint32_t>(0),
            static_cast<uint32_t>(0)};
        const AscendC::DataCopyPadExtParams<float> padParams{true, 0, 7, 0.0f};

        for (uint32_t task = core; task < totalTasks; task += blockCount) {
            const uint32_t b = task / c;
            const uint32_t ch = task - b * c;
            AscendC::LocalTensor<float> pSeg = pSegBuf.Get<float>();
            for (uint32_t pos = 0; pos < rowValid; ++pos) {
                const uint64_t pIndex = ((uint64_t)b * (uint64_t)hw + (uint64_t)pos) * (uint64_t)c + ch;
                pSeg.SetValue(pos, pGm.GetValue(pIndex));
            }
            for (uint32_t pos = rowValid; pos < rowStorage; ++pos) {
                pSeg.SetValue(pos, 0.0f);
            }

            const uint64_t rowBase = (uint64_t)task * (uint64_t)hw;
            AscendC::LocalTensor<float> cRow = cRowQueue.AllocTensor<float>();
            AscendC::DataCopyPad(cRow, cGm[rowBase], copyParams, padParams);
            cRowQueue.EnQue(cRow);
            cRow = cRowQueue.DeQue<float>();

            AscendC::LocalTensor<float> outRow = outRowQueue.AllocTensor<float>();
            AscendC::Add(outRow, pSeg, cRow, rowStorage);
            cRowQueue.FreeTensor(cRow);
            outRowQueue.EnQue(outRow);
            outRow = outRowQueue.DeQue<float>();
            AscendC::DataCopyPad(yGm[rowBase], outRow, copyParams);
            outRowQueue.FreeTensor(outRow);
        }
    }

private:
    AscendC::TPipe pipe;

    AscendC::TBuf<AscendC::TPosition::VECCALC> pSegBuf;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> cRowQueue;
    AscendC::TQue<AscendC::TPosition::VECOUT, 1> outRowQueue;

    AscendC::GlobalTensor<float> pGm;
    AscendC::GlobalTensor<float> cGm;
    AscendC::GlobalTensor<float> yGm;

    uint32_t bs, c, hw;
    uint32_t totalTasks, rowValid, rowStorage;
};

extern "C" __global__ __aicore__ void da_module_custom(GM_ADDR p_out, GM_ADDR c_out, GM_ADDR y, GM_ADDR workspace, GM_ADDR tiling)
{
    GET_TILING_DATA(tiling_data, tiling);
    KernelDAModuleCustom op;
    op.Init(p_out, c_out, y,
            tiling_data.bs, tiling_data.c, tiling_data.hw,
            tiling_data.totalTasks, tiling_data.rowValid,
            tiling_data.rowStorage);
    op.Process();
}

