#include "kernel_operator.h"

class KernelDAModuleCustom {
public:
    __aicore__ inline KernelDAModuleCustom() {}

    __aicore__ inline void Init(GM_ADDR p_out, GM_ADDR c_out, GM_ADDR y,
                               uint32_t bs, uint32_t c, uint32_t hw,
                               uint32_t totalTasks, uint32_t channelPack, uint32_t rowValid,
                               uint32_t rowStorage)
    {
        this->bs = bs;
        this->c = c;
        this->hw = hw;
        this->totalTasks = totalTasks;
        this->channelPack = channelPack;
        this->rowValid = rowValid;
        this->rowStorage = rowStorage;

        const uint64_t totalP = (uint64_t)bs * (uint64_t)hw * (uint64_t)c;
        const uint64_t totalC = (uint64_t)bs * (uint64_t)c  * (uint64_t)hw;

        pGm.SetGlobalBuffer((__gm__ float*)p_out, totalP); // [bs, hw, c]
        cGm.SetGlobalBuffer((__gm__ float*)c_out, totalC); // [bs, c, hw]
        yGm.SetGlobalBuffer((__gm__ float*)y,     totalC); // write as flat [bs, c, hw] (matches contiguous NCHW storage)

        const uint32_t packedBytes = rowValid * channelPack * static_cast<uint32_t>(sizeof(float));
        const uint32_t groupedRowBytes = channelPack * rowStorage * static_cast<uint32_t>(sizeof(float));
        pipe.InitBuffer(pPackedQueue, 1, packedBytes);
        pipe.InitBuffer(pRowsBuf, groupedRowBytes);
        pipe.InitBuffer(cRowsQueue, 1, groupedRowBytes);
        pipe.InitBuffer(outRowsQueue, 1, groupedRowBytes);
    }

    __aicore__ inline void Process()
    {
        const uint32_t core = (uint32_t)AscendC::GetBlockIdx();
        const uint32_t blockCount = static_cast<uint32_t>(AscendC::GetBlockNum());
        const uint32_t elementBytes = static_cast<uint32_t>(sizeof(float));
        const uint32_t rowBytes = rowValid * elementBytes;
        const uint32_t packedBlockBytes = channelPack * elementBytes;
        const uint32_t pSrcStrideBytes = (c - channelPack) * elementBytes;
        const AscendC::DataCopyExtParams pCopyParams{
            static_cast<uint16_t>(rowValid), packedBlockBytes, pSrcStrideBytes, static_cast<uint32_t>(0),
            static_cast<uint32_t>(0)};
        const AscendC::DataCopyExtParams rowGroupCopyParams{
            static_cast<uint16_t>(channelPack), rowBytes, static_cast<uint32_t>(0), static_cast<uint32_t>(0),
            static_cast<uint32_t>(0)};
        const AscendC::DataCopyPadExtParams<float> noPadParams{false, 0, 0, 0.0f};
        const AscendC::DataCopyPadExtParams<float> rowPadParams{true, 0, 7, 0.0f};

        for (uint32_t task = core; task < totalTasks; task += blockCount) {
            const uint32_t groupsPerBatch = c / channelPack;
            const uint32_t b = task / groupsPerBatch;
            const uint32_t group = task - b * groupsPerBatch;
            const uint32_t chBase = group * channelPack;

            const uint64_t pBase = static_cast<uint64_t>(b) * static_cast<uint64_t>(hw) *
                                       static_cast<uint64_t>(c) +
                                   static_cast<uint64_t>(chBase);
            AscendC::LocalTensor<float> pPacked = pPackedQueue.AllocTensor<float>();
            AscendC::DataCopyPad(pPacked, pGm[pBase], pCopyParams, noPadParams);
            pPackedQueue.EnQue(pPacked);
            pPacked = pPackedQueue.DeQue<float>();

            event_t mte2ToScalar = static_cast<event_t>(
                GetTPipePtr()->FetchEventID(AscendC::HardEvent::MTE2_S));
            AscendC::SetFlag<AscendC::HardEvent::MTE2_S>(mte2ToScalar);
            AscendC::WaitFlag<AscendC::HardEvent::MTE2_S>(mte2ToScalar);
            AscendC::LocalTensor<float> pRows = pRowsBuf.Get<float>();
            for (uint32_t pos = 0; pos < rowValid; ++pos) {
                for (uint32_t lane = 0; lane < channelPack; ++lane) {
                    pRows.SetValue(lane * rowStorage + pos, pPacked.GetValue(pos * channelPack + lane));
                }
            }
            event_t scalarToMte2 = static_cast<event_t>(
                GetTPipePtr()->FetchEventID(AscendC::HardEvent::S_MTE2));
            AscendC::SetFlag<AscendC::HardEvent::S_MTE2>(scalarToMte2);
            AscendC::WaitFlag<AscendC::HardEvent::S_MTE2>(scalarToMte2);
            pPackedQueue.FreeTensor(pPacked);
            for (uint32_t lane = 0; lane < channelPack; ++lane) {
                for (uint32_t pos = rowValid; pos < rowStorage; ++pos) {
                    pRows.SetValue(lane * rowStorage + pos, 0.0f);
                }
            }

            event_t scalarToVector = static_cast<event_t>(
                GetTPipePtr()->FetchEventID(AscendC::HardEvent::S_V));
            AscendC::SetFlag<AscendC::HardEvent::S_V>(scalarToVector);
            AscendC::WaitFlag<AscendC::HardEvent::S_V>(scalarToVector);

            const uint64_t rowBase = (static_cast<uint64_t>(b) * static_cast<uint64_t>(c) +
                                      static_cast<uint64_t>(chBase)) * static_cast<uint64_t>(hw);
            AscendC::LocalTensor<float> cRows = cRowsQueue.AllocTensor<float>();
            AscendC::DataCopyPad(cRows, cGm[rowBase], rowGroupCopyParams, rowPadParams);
            cRowsQueue.EnQue(cRows);
            cRows = cRowsQueue.DeQue<float>();

            AscendC::LocalTensor<float> outRows = outRowsQueue.AllocTensor<float>();
            for (uint32_t lane = 0; lane < channelPack; ++lane) {
                const uint32_t rowOffset = lane * rowStorage;
                AscendC::Add(outRows[rowOffset], pRows[rowOffset], cRows[rowOffset], rowStorage);
            }
            cRowsQueue.FreeTensor(cRows);
            outRowsQueue.EnQue(outRows);
            outRows = outRowsQueue.DeQue<float>();
            AscendC::DataCopyPad(yGm[rowBase], outRows, rowGroupCopyParams);
            outRowsQueue.FreeTensor(outRows);
        }
    }

private:
    AscendC::TPipe pipe;

    AscendC::TQue<AscendC::TPosition::VECIN, 1> pPackedQueue;
    AscendC::TBuf<AscendC::TPosition::VECCALC> pRowsBuf;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> cRowsQueue;
    AscendC::TQue<AscendC::TPosition::VECOUT, 1> outRowsQueue;

    AscendC::GlobalTensor<float> pGm;
    AscendC::GlobalTensor<float> cGm;
    AscendC::GlobalTensor<float> yGm;

    uint32_t bs, c, hw;
    uint32_t totalTasks, channelPack, rowValid, rowStorage;
};

extern "C" __global__ __aicore__ void da_module_custom(GM_ADDR p_out, GM_ADDR c_out, GM_ADDR y, GM_ADDR workspace, GM_ADDR tiling)
{
    GET_TILING_DATA(tiling_data, tiling);
    KernelDAModuleCustom op;
    op.Init(p_out, c_out, y,
            tiling_data.bs, tiling_data.c, tiling_data.hw,
            tiling_data.totalTasks, tiling_data.channelPack, tiling_data.rowValid,
            tiling_data.rowStorage);
    op.Process();
