    constexpr uint32_t channelPack = 8U;
    if (c % channelPack != 0U) return ge::GRAPH_FAILED;
    const uint32_t totalTasks = bs * (c / channelPack);
    const uint32_t rowValid = hw;
    const uint32_t rowStorage = (rowValid + 7U) & ~7U;
    const uint32_t blockDim = std::min(std::max(1U, totalTasks), 48U);
