#include "kernel_operator.h"

class KernelECAAttentionCustom {
public:
    __aicore__ inline KernelECAAttentionCustom() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR weight, GM_ADDR y,
                               uint32_t B, uint32_t C, uint32_t H, uint32_t W,
                               uint32_t HW, uint32_t K, uint32_t pad,
                               float invHW, uint32_t cTile, uint32_t sigTmpBytes,
                               uint32_t totalB, uint32_t bPerBlock)
    {
        this->B = B;
        this->C = C;
        this->H = H;
        this->W = W;
        this->HW = HW;
        this->K = K;
        this->pad = pad;
        this->invHW = invHW;
        this->cTile = cTile;
        this->sigTmpBytes = sigTmpBytes;

        const uint32_t blk = static_cast<uint32_t>(AscendC::GetBlockIdx());
        blockIdx = static_cast<uint32_t>(AscendC::GetBlockIdx());
        blockNum = static_cast<uint32_t>(AscendC::GetBlockNum());
        (void)totalB;
        (void)bPerBlock;

        const uint64_t totalX = static_cast<uint64_t>(B) * C * H * W;
        xGm.SetGlobalBuffer((__gm__ float*)x, totalX);
        yGm.SetGlobalBuffer((__gm__ float*)y, totalX);
        wGm.SetGlobalBuffer((__gm__ float*)weight, static_cast<uint64_t>(K));

        storageHW = ((HW + 7U) / 8U) * 8U;
        tileElements = cTile * storageHW;
        pipe.InitBuffer(xQueue, 1, static_cast<uint64_t>(tileElements) * sizeof(float));
        pipe.InitBuffer(yQueue, 1, static_cast<uint64_t>(tileElements) * sizeof(float));
        pipe.InitBuffer(weightQueue, 1, 8U * sizeof(float));
        pipe.InitBuffer(pooledBuf, static_cast<uint64_t>(C + 16U) * sizeof(float));
        pipe.InitBuffer(tapBuf, static_cast<uint64_t>(K) * cTile * sizeof(float));
        pipe.InitBuffer(outTileBuf, static_cast<uint64_t>(cTile) * sizeof(float));
        pipe.InitBuffer(gateBuf, static_cast<uint64_t>(cTile) * sizeof(float));
        pipe.InitBuffer(sigTmpBuf, static_cast<uint64_t>(sigTmpBytes));
    }

    __aicore__ inline void Process()
    {
        if (B == 0 || C == 0 || H == 0 || W == 0 || HW == 0 || K == 0) return;
        if (blockNum == 0 || blockIdx >= B) return;

        AscendC::LocalTensor<float> weightLocal = weightQueue.AllocTensor<float>();
        AscendC::DataCopyExtParams weightCopy{1U, K * static_cast<uint32_t>(sizeof(float)), 0U, 0U, 0U};
        AscendC::DataCopyPadExtParams<float> weightPad{true, 0U, 0U, 0.0f};
        AscendC::DataCopyPad(weightLocal, wGm, weightCopy, weightPad);
        weightQueue.EnQue(weightLocal);
        weightLocal = weightQueue.DeQue<float>();

        for (uint32_t b = blockIdx; b < B; b += blockNum) {
            ComputeOneBatch(b, weightLocal);
        }
        weightQueue.FreeTensor(weightLocal);
    }

private:
    __aicore__ inline uint64_t XOff(uint32_t b, uint32_t c, uint32_t hw) const
    {
        return (static_cast<uint64_t>(b) * C + c) * static_cast<uint64_t>(HW) + hw;
    }

    __aicore__ inline void CopyIn(uint32_t b, uint32_t c0, uint32_t validC)
    {
        AscendC::LocalTensor<float> xLocal = xQueue.AllocTensor<float>();
        const uint32_t rowBytes = HW * static_cast<uint32_t>(sizeof(float));
        AscendC::DataCopyExtParams copy{static_cast<uint16_t>(validC), rowBytes, 0U, 0U, 0U};
        AscendC::DataCopyPadExtParams<float> padParam{true, 0U,
            static_cast<uint8_t>(storageHW - HW), 0.0f};
        AscendC::DataCopyPad(xLocal, xGm[XOff(b, c0, 0)], copy, padParam);
        xQueue.EnQue(xLocal);
    }

    __aicore__ inline void CopyOut(uint32_t b, uint32_t c0, uint32_t validC,
                                   AscendC::LocalTensor<float>& yLocal)
    {
        yQueue.EnQue(yLocal);
        AscendC::LocalTensor<float> ready = yQueue.DeQue<float>();
        const uint32_t rowBytes = HW * static_cast<uint32_t>(sizeof(float));
        AscendC::DataCopyExtParams copy{static_cast<uint16_t>(validC), rowBytes, 0U, 0U, 0U};
        AscendC::DataCopyPad(yGm[XOff(b, c0, 0)], ready, copy);
        yQueue.FreeTensor(ready);
    }

    __aicore__ inline void ComputeOneBatch(uint32_t b, const AscendC::LocalTensor<float>& weightLocal)
    {
        AscendC::LocalTensor<float> pooled = pooledBuf.Get<float>();
        AscendC::LocalTensor<float> taps = tapBuf.Get<float>();
        AscendC::LocalTensor<float> outTile = outTileBuf.Get<float>();
        AscendC::LocalTensor<float> gate = gateBuf.Get<float>();
        AscendC::LocalTensor<int32_t> gatherOffsetSigned = gateBuf.Get<int32_t>();
        AscendC::LocalTensor<uint32_t> gatherOffset = gateBuf.Get<uint32_t>();
        AscendC::LocalTensor<uint8_t> sigTmp = sigTmpBuf.Get<uint8_t>();

        const uint32_t numTiles = (C + cTile - 1U) / cTile;
        AscendC::Duplicate(pooled, 0.0f, static_cast<int32_t>(C + 16U));
        AscendC::PipeBarrier<PIPE_V>();
        for (uint32_t t = 0; t < numTiles; ++t) {
            const uint32_t c0 = t * cTile;
            const uint32_t validC = (c0 + cTile <= C) ? cTile : (C - c0);
            CopyIn(b, c0, validC);
            AscendC::LocalTensor<float> xLocal = xQueue.DeQue<float>();
            for (uint32_t i = 0; i < validC; ++i) {
                AscendC::ReduceSum(outTile, xLocal[i * storageHW], gate, static_cast<int32_t>(HW));
                AscendC::PipeBarrier<PIPE_V>();
                pooled.SetValue(8U + c0 + i, outTile.GetValue(0) * invHW);
            }
            xQueue.FreeTensor(xLocal);
        }
        AscendC::PipeBarrier<PIPE_V>();

        for (uint32_t t = 0; t < numTiles; ++t) {
            const uint32_t c0 = t * cTile;
            const uint32_t curC = (c0 + cTile <= C) ? cTile : (C - c0);
            if (curC == 0) continue;

            for (uint32_t kk = 0; kk < K; ++kk) {
                AscendC::LocalTensor<float> tap = taps[kk * cTile];
                const int32_t firstByte = static_cast<int32_t>(
                    (8U + c0 + kk - pad) * static_cast<uint32_t>(sizeof(float)));
                AscendC::ArithProgression(gatherOffsetSigned, firstByte,
                    static_cast<int32_t>(sizeof(float)), static_cast<int32_t>(curC));
                AscendC::PipeBarrier<PIPE_V>();
                AscendC::Gather(tap, pooled, gatherOffset, 0U, curC);
            }
            AscendC::PipeBarrier<PIPE_V>();

            AscendC::Muls(outTile, taps, weightLocal.GetValue(0), static_cast<int32_t>(curC));
            for (uint32_t kk = 1; kk < K; ++kk) {
                AscendC::Muls(gate, taps[kk * cTile], weightLocal.GetValue(kk), static_cast<int32_t>(curC));
                AscendC::PipeBarrier<PIPE_V>();
                AscendC::Add(outTile, outTile, gate, static_cast<int32_t>(curC));
                AscendC::PipeBarrier<PIPE_V>();
            }

            AscendC::Sigmoid<float, true>(gate, outTile, sigTmp, curC);
            AscendC::PipeBarrier<PIPE_V>();

            CopyIn(b, c0, curC);
            AscendC::LocalTensor<float> xLocal = xQueue.DeQue<float>();
            AscendC::LocalTensor<float> yLocal = yQueue.AllocTensor<float>();
            for (uint32_t i = 0; i < curC; ++i) {
                AscendC::Duplicate(yLocal[i * storageHW], gate.GetValue(i), static_cast<int32_t>(HW));
                AscendC::PipeBarrier<PIPE_V>();
                AscendC::Mul(yLocal[i * storageHW], xLocal[i * storageHW],
                             yLocal[i * storageHW], static_cast<int32_t>(HW));
            }
            xQueue.FreeTensor(xLocal);
            CopyOut(b, c0, curC, yLocal);
        }
    }

private:
    AscendC::TPipe pipe;

    AscendC::TBuf<AscendC::TPosition::VECCALC> pooledBuf;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> xQueue;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> weightQueue;
    AscendC::TQue<AscendC::TPosition::VECOUT, 1> yQueue;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tapBuf;
    AscendC::TBuf<AscendC::TPosition::VECCALC> outTileBuf;
    AscendC::TBuf<AscendC::TPosition::VECCALC> gateBuf;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sigTmpBuf;

    AscendC::GlobalTensor<float> xGm;
    AscendC::GlobalTensor<float> yGm;
    AscendC::GlobalTensor<float> wGm;

    uint32_t B, C, H, W, HW, K, pad;
    float invHW;
    uint32_t cTile;
    uint32_t sigTmpBytes;

    uint32_t storageHW, tileElements;
    uint32_t blockIdx, blockNum;
};

extern "C" __global__ __aicore__ void eca_attention_custom(
    GM_ADDR x, GM_ADDR weight, GM_ADDR y, GM_ADDR workspace, GM_ADDR tiling)
{
    (void)workspace;
    GET_TILING_DATA(tiling_data, tiling);
    KernelECAAttentionCustom op;
    op.Init(x, weight, y,
            tiling_data.B, tiling_data.C, tiling_data.H, tiling_data.W,
            tiling_data.HW, tiling_data.K, tiling_data.pad,
            tiling_data.invHW, tiling_data.cTile, tiling_data.sigTmpBytes,
            tiling_data.totalB, tiling_data.bPerBlock);
    op.Process();
}

