                AscendC::PipeBarrier<PIPE_V>();
                pooled.SetValue(8U + c0 + i, yLocal.GetValue(0) * invHW);
            }
        }
        AscendC::PipeBarrier<PIPE_V>();

        for (uint32_t t = 0; t < numTiles; ++t) {
            const uint32_t c0 = t * cTile;
            const uint32_t curC = (c0 + cTile <= C) ? cTile : (C - c0);
            if (curC == 0) continue;

