            AscendC::LocalTensor<float> outTile = yLocal[K * cTile];
            AscendC::LocalTensor<int32_t> gatherOffsetSigned = outTile.template ReinterpretCast<int32_t>();
            AscendC::LocalTensor<uint32_t> gatherOffset = outTile.template ReinterpretCast<uint32_t>();
            AscendC::LocalTensor<uint8_t> sigTmp = yLocal[(K + 1U) * cTile]
                .template ReinterpretCast<uint8_t>();

            for (uint32_t kk = 0; kk < K; ++kk) {
                AscendC::LocalTensor<float> tap = taps[kk * cTile];
                const int32_t firstByte = static_cast<int32_t>(
                    (8U + c0 + kk - pad) * static_cast<uint32_t>(sizeof(float)));
                AscendC::ArithProgression(gatherOffsetSigned, firstByte,
                    static_cast<int32_t>(sizeof(float)), static_cast<int32_t>(curC));
                AscendC::PipeBarrier<PIPE_V>();
                AscendC::Gather(tap, pooled, gatherOffset, 0U, curC);
            }
            AscendC::PipeBarrier<PIPE_V>();

            AscendC::Muls(outTile, taps, weightLocal.GetValue(0), static_cast<int32_t>(curC));
            for (uint32_t kk = 1; kk < K; ++kk) {
                AscendC::Muls(pooled, taps[kk * cTile], weightLocal.GetValue(kk), static_cast<int32_t>(curC));
                AscendC::PipeBarrier<PIPE_V>();
                AscendC::Add(outTile, outTile, pooled, static_cast<int32_t>(curC));
                AscendC::PipeBarrier<PIPE_V>();
            }

            AscendC::Sigmoid<float, true>(pooled, outTile, sigTmp, curC);
            AscendC::PipeBarrier<PIPE_V>();

            for (uint32_t i = 0; i < curC; ++i) {
                AscendC::Duplicate(yLocal[i * storageHW], pooled.GetValue(i), static_cast<int32_t>(HW));
                AscendC::PipeBarrier<PIPE_V>();
                AscendC::Mul(yLocal[i * storageHW], residentX[(c0 + i) * storageHW],
                             yLocal[i * storageHW], static_cast<int32_t>(HW));
            }
            CopyOut(b, c0, curC, yLocal);
        }
        xQueue.FreeTensor(residentX);
    }

private:
    AscendC::TPipe pipe;

    AscendC::TBuf<AscendC::TPosition::VECCALC> pooledBuf;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> xQueue;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> weightQueue;
    AscendC::TQue<AscendC::TPosition::VECOUT, 1> yQueue;

    AscendC::GlobalTensor<float> xGm;
    AscendC::GlobalTensor<float> yGm;
    AscendC::GlobalTensor<float> wGm;

    uint32_t B, C, H, W, HW, K, pad;
    float invHW;
    uint32_t cTile;
    uint32_t sigTmpBytes;

    uint32_t storageHW, tileElements, residentElements;
    uint32_t blockIdx, blockNum;
};

extern "C" __global__ __aicore__ void eca_attention_custom(
    GM_ADDR x, GM_ADDR weight, GM_ADDR y, GM_ADDR workspace, GM_ADDR tiling)
{
    (void)workspace;
    GET_TILING_DATA(tiling_data, tiling);
    KernelECAAttentionCustom op;
    op.Init(x, weight, y,
            tiling_data.B, tiling_data.C, tiling_data.H, tiling_data.W,
            tiling_data.HW, tiling_data.K, tiling_data.pad,
            tiling_data.invHW, tiling_data.cTile, tiling_data.sigTmpBytes,
            tiling_data.totalB, tiling_data.bPerBlock);
    op.Process();
}

