    uint32_t CHW = C * HW;
    if (CHW == 0U) return ge::GRAPH_FAILED;

    uint32_t totalLength = N * CHW;
    if (totalLength == 0U) return ge::GRAPH_FAILED;
    uint32_t CAlign = AlignUp(C, 8U);
    if (CAlign == 0U) CAlign = 8U;

