#include "kernel_operator.h"

class KernelGlobalFilterCustom {
public:
    __aicore__ inline KernelGlobalFilterCustom() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR w, GM_ADDR y,
                               uint32_t B, uint32_t N, uint32_t C,
                               uint32_t H, uint32_t W, uint32_t FW,
                               uint32_t xTotal, uint32_t wTotal,
                               float invSqrtHW, uint32_t cTile,
                               uint32_t batchGroups)
    {
        this->B = static_cast<int32_t>(B);
        this->N = static_cast<int32_t>(N);
        this->C = static_cast<int32_t>(C);
        this->H = static_cast<int32_t>(H);
        this->W = static_cast<int32_t>(W);
        this->FW = static_cast<int32_t>(FW);
        this->invSqrtHW = invSqrtHW;
        this->cTile = static_cast<int32_t>(cTile);
        this->batchGroups = static_cast<int32_t>(batchGroups);

        xGm.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(x), static_cast<uint64_t>(xTotal));
        yGm.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(y), static_cast<uint64_t>(xTotal));
        wGm.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(w), static_cast<uint64_t>(wTotal));

        constexpr uint32_t planeBytes = 128U * sizeof(float);
        pipe.InitBuffer(wSlabBuf, 28U * 128U * 2U * sizeof(float));
        pipe.InitBuffer(xTileBuf, 49U * planeBytes);
        pipe.InitBuffer(yTileBuf, 49U * planeBytes);
        pipe.InitBuffer(xReBuf, planeBytes);
        pipe.InitBuffer(xImBuf, planeBytes);
        pipe.InitBuffer(yReBuf, planeBytes);
        pipe.InitBuffer(yImBuf, planeBytes);
        pipe.InitBuffer(wReBuf, planeBytes);
        pipe.InitBuffer(wImBuf, planeBytes);
        pipe.InitBuffer(tmp0Buf, planeBytes);
        pipe.InitBuffer(tmp1Buf, planeBytes);
        pipe.InitBuffer(offsetReBuf, planeBytes);
        pipe.InitBuffer(offsetImBuf, planeBytes);

        eventMte2ToV = pipe.FetchEventID(AscendC::HardEvent::MTE2_V);
        eventVToMte2 = pipe.FetchEventID(AscendC::HardEvent::V_MTE2);
        eventVToMte3 = pipe.FetchEventID(AscendC::HardEvent::V_MTE3);
        eventMte3ToV = pipe.FetchEventID(AscendC::HardEvent::MTE3_V);
        eventSToV = pipe.FetchEventID(AscendC::HardEvent::S_V);
    }

    __aicore__ inline void Process()
    {
        if (B != 32 || H != 7 || W != 7 || FW != 4 || C != 512 || N != 49 ||
            cTile != 128 || batchGroups != 12) {
            return;
        }
        const int32_t task = static_cast<int32_t>(AscendC::GetBlockIdx());
        const int32_t totalTasks = (C / cTile) * batchGroups;
        if (task < 0 || task >= totalTasks) return;

        const int32_t cTileId = task / batchGroups;
        const int32_t batchGroup = task - cTileId * batchGroups;
        const int32_t cStart = cTileId * cTile;
        const int32_t bBegin = batchGroup * B / batchGroups;
        const int32_t bEnd = (batchGroup + 1) * B / batchGroups;
        ProcessOneBatchTile(cStart, bBegin, bEnd);
    }

private:
    __aicore__ inline void ProcessOneBatchTile(int32_t cStart, int32_t bBegin, int32_t bEnd)
    {
        auto wSlab = wSlabBuf.Get<float>();
        auto xTile = xTileBuf.Get<float>();
        auto yTile = yTileBuf.Get<float>();
        auto offsetRe = offsetReBuf.Get<uint32_t>();
        auto offsetIm = offsetImBuf.Get<uint32_t>();

        for (int32_t lane = 0; lane < 128; ++lane) {
            offsetRe.SetValue(static_cast<uint32_t>(lane), static_cast<uint32_t>(lane * 8));
            offsetIm.SetValue(static_cast<uint32_t>(lane), static_cast<uint32_t>(lane * 8 + 4));
        }
        AscendC::SetFlag<AscendC::HardEvent::S_V>(eventSToV);
        AscendC::WaitFlag<AscendC::HardEvent::S_V>(eventSToV);

        for (int32_t q = 0; q < 28; ++q) {
            const uint64_t src = static_cast<uint64_t>(q) * static_cast<uint64_t>(C) * 2ULL +
                                 static_cast<uint64_t>(cStart) * 2ULL;
            AscendC::DataCopy(wSlab[static_cast<uint32_t>(q * 256)], wGm[src], 256U);
        }
        AscendC::SetFlag<AscendC::HardEvent::MTE2_V>(eventMte2ToV);
        AscendC::WaitFlag<AscendC::HardEvent::MTE2_V>(eventMte2ToV);

        const AscendC::DataCopyExtParams xParams(49U, 512U, 1536U, 0U, 0U);
        const AscendC::DataCopyExtParams yParams(49U, 512U, 0U, 1536U, 0U);
        const AscendC::DataCopyPadExtParams<float> noPad(false, 0U, 0U, 0.0f);

        for (int32_t b = bBegin; b < bEnd; ++b) {
            const uint64_t base = static_cast<uint64_t>(b) * 49ULL * 512ULL +
                                  static_cast<uint64_t>(cStart);
            AscendC::DataCopyPad(xTile, xGm[base], xParams, noPad);
            AscendC::SetFlag<AscendC::HardEvent::MTE2_V>(eventMte2ToV);
            AscendC::WaitFlag<AscendC::HardEvent::MTE2_V>(eventMte2ToV);

            AscendC::Duplicate(yTile, 0.0f, 49 * 128);
            for (int32_t k = 0; k < 7; ++k) {
                for (int32_t l = 0; l < 4; ++l) {
                    const int32_t q = k * 4 + l;
                    ForwardRFFT2_7x7_FromRegs(k, l, xTile);
                    MultiplyWeight_FromSlab(q, wSlab, offsetRe, offsetIm);
                    InverseIRFFT2_7x7_ToUB(k, l, yTile);
                }
            }
            AscendC::Muls(yTile, yTile, invSqrtHW, 49 * 128);

            AscendC::SetFlag<AscendC::HardEvent::V_MTE2>(eventVToMte2);
            AscendC::WaitFlag<AscendC::HardEvent::V_MTE2>(eventVToMte2);
            AscendC::SetFlag<AscendC::HardEvent::V_MTE3>(eventVToMte3);
            AscendC::WaitFlag<AscendC::HardEvent::V_MTE3>(eventVToMte3);
            AscendC::DataCopyPad(yGm[base], yTile, yParams);
            AscendC::SetFlag<AscendC::HardEvent::MTE3_V>(eventMte3ToV);
            AscendC::WaitFlag<AscendC::HardEvent::MTE3_V>(eventMte3ToV);
        }
    }

    __aicore__ inline void ForwardRFFT2_7x7_FromRegs(int32_t k, int32_t l,
                                                     const AscendC::LocalTensor<float>& xTile)
    {
        auto xRe = xReBuf.Get<float>();
        auto xIm = xImBuf.Get<float>();
        auto tmp0 = tmp0Buf.Get<float>();
        AscendC::Duplicate(xRe, 0.0f, 128);
        AscendC::Duplicate(xIm, 0.0f, 128);
        for (int32_t n = 0; n < 7; ++n) {
            const int32_t tn = (k * n) % 7;
            const float ca = Cos7(tn);
            const float sa = Sin7(tn);
            for (int32_t m = 0; m < 7; ++m) {
                float cosab = ca;
                float sinab = sa;
                if (l != 0) {
                    const int32_t tm = (l * m) % 7;
                    const float cb = Cos7(tm);
                    const float sb = Sin7(tm);
                    cosab = ca * cb - sa * sb;
                    sinab = sa * cb + ca * sb;
                }
                const auto xPlane = xTile[static_cast<uint32_t>((n * 7 + m) * 128)];
                AscendC::Muls(tmp0, xPlane, cosab, 128);
                AscendC::Add(xRe, xRe, tmp0, 128);
                AscendC::Muls(tmp0, xPlane, -sinab, 128);
                AscendC::Add(xIm, xIm, tmp0, 128);
            }
        }
        AscendC::Muls(xRe, xRe, invSqrtHW, 128);
        AscendC::Muls(xIm, xIm, invSqrtHW, 128);
    }

    __aicore__ inline void MultiplyWeight_FromSlab(int32_t q,
                                                   const AscendC::LocalTensor<float>& wSlab,
                                                   const AscendC::LocalTensor<uint32_t>& offsetRe,
                                                   const AscendC::LocalTensor<uint32_t>& offsetIm)
    {
        auto xRe = xReBuf.Get<float>();
        auto xIm = xImBuf.Get<float>();
        auto yRe = yReBuf.Get<float>();
        auto yIm = yImBuf.Get<float>();
        auto wRe = wReBuf.Get<float>();
        auto wIm = wImBuf.Get<float>();
        auto tmp0 = tmp0Buf.Get<float>();
        auto tmp1 = tmp1Buf.Get<float>();
        const auto wPlane = wSlab[static_cast<uint32_t>(q * 256)];
        AscendC::Gather(wRe, wPlane, offsetRe, 0U, 128U);
        AscendC::Gather(wIm, wPlane, offsetIm, 0U, 128U);
        AscendC::Mul(tmp0, xRe, wRe, 128);
        AscendC::Mul(tmp1, xIm, wIm, 128);
        AscendC::Sub(yRe, tmp0, tmp1, 128);
        AscendC::Mul(tmp0, xRe, wIm, 128);
        AscendC::Mul(tmp1, xIm, wRe, 128);
        AscendC::Add(yIm, tmp0, tmp1, 128);
    }

    __aicore__ inline void InverseIRFFT2_7x7_ToUB(int32_t k, int32_t l,
                                                  const AscendC::LocalTensor<float>& yTile)
    {
        auto yRe = yReBuf.Get<float>();
        auto yIm = yImBuf.Get<float>();
        auto tmp0 = tmp0Buf.Get<float>();
        auto tmp1 = tmp1Buf.Get<float>();
        for (int32_t n0 = 0; n0 < 7; ++n0) {
            const int32_t tn = (k * n0) % 7;
            const float ca = Cos7(tn);
            const float sa = Sin7(tn);
            for (int32_t m0 = 0; m0 < 7; ++m0) {
                float cosab = ca;
                float sinab = sa;
                if (l != 0) {
                    const int32_t tm = (l * m0) % 7;
                    const float cb = Cos7(tm);
                    const float sb = Sin7(tm);
                    cosab = ca * cb - sa * sb;
                    sinab = sa * cb + ca * sb;
                }
                AscendC::Muls(tmp0, yRe, cosab, 128);
                AscendC::Muls(tmp1, yIm, sinab, 128);
                AscendC::Sub(tmp0, tmp0, tmp1, 128);
                if (l != 0) AscendC::Muls(tmp0, tmp0, 2.0f, 128);
                auto yPlane = yTile[static_cast<uint32_t>((n0 * 7 + m0) * 128)];
                AscendC::Add(yPlane, yPlane, tmp0, 128);
            }
        }
    }

    __aicore__ inline float Cos7(int32_t i) const
    {
        const float table[7] = {1.0f, 0.623489802f, -0.222520934f, -0.900968868f,
                                -0.900968868f, -0.222520934f, 0.623489802f};
        return table[i];
    }

    __aicore__ inline float Sin7(int32_t i) const
    {
        const float table[7] = {0.0f, 0.781831482f, 0.974927912f, 0.433883739f,
                                -0.433883739f, -0.974927912f, -0.781831482f};
        return table[i];
    }

private:
    AscendC::TPipe pipe;
    AscendC::TBuf<> wSlabBuf, xTileBuf, yTileBuf;
    AscendC::TBuf<> xReBuf, xImBuf, yReBuf, yImBuf, wReBuf, wImBuf;
    AscendC::TBuf<> tmp0Buf, tmp1Buf, offsetReBuf, offsetImBuf;
    AscendC::GlobalTensor<float> xGm, yGm, wGm;
    AscendC::TEventID eventMte2ToV, eventVToMte2, eventVToMte3, eventMte3ToV, eventSToV;
    int32_t B{0}, N{0}, C{0}, H{0}, W{0}, FW{0};
    float invSqrtHW{0.0f};
    int32_t cTile{128}, batchGroups{12};
};

extern "C" __global__ __aicore__ void global_filter_custom(
    GM_ADDR x, GM_ADDR complex_weight, GM_ADDR y, GM_ADDR workspace, GM_ADDR tiling)
{
    GET_TILING_DATA(tiling_data, tiling);
    KernelGlobalFilterCustom op;
    op.Init(x, complex_weight, y,
            tiling_data.B, tiling_data.N, tiling_data.C,
            tiling_data.H, tiling_data.W, tiling_data.FW,
            tiling_data.xTotal, tiling_data.wTotal,
            tiling_data.invSqrtHW, tiling_data.cTile, tiling_data.batchGroups);
    op.Process();
}

