#include "kernel_operator.h"
class KernelHaloAttentionCustom {
public:
    __aicore__ inline KernelHaloAttentionCustom() {}

    __aicore__ inline void Init(GM_ADDR q, GM_ADDR k, GM_ADDR v, GM_ADDR mask, GM_ADDR out,
                               uint32_t B, uint32_t I, uint32_t J, uint32_t D)
    {
        this->B = B; this->I = I; this->J = J; this->D = D;
        this->totalRows = B * I;

        const uint64_t qElems  = static_cast<uint64_t>(B) * I * D;
        const uint64_t kvElems = static_cast<uint64_t>(B) * J * D;
        const uint64_t mElems  = static_cast<uint64_t>(B) * 1ULL * J;
        const uint64_t oElems  = static_cast<uint64_t>(B) * I * D;

        qGm.SetGlobalBuffer((__gm__ float*)q, qElems);
        kGm.SetGlobalBuffer((__gm__ float*)k, kvElems);
        vGm.SetGlobalBuffer((__gm__ float*)v, kvElems);
        mGm.SetGlobalBuffer((__gm__ uint8_t*)mask, mElems);
        oGm.SetGlobalBuffer((__gm__ float*)out, oElems);

        pipe.InitBuffer(qQueue, 1, I * D * sizeof(float));
        pipe.InitBuffer(kQueue, 1, D * sizeof(float));
        pipe.InitBuffer(vQueue, 1, D * sizeof(float));
        pipe.InitBuffer(maskQueue, 1, 32U);
        pipe.InitBuffer(bufScores, I * J * sizeof(float));
        pipe.InitBuffer(bufProbs, I * J * sizeof(float));
        pipe.InitBuffer(outQueue, 1, I * D * sizeof(float));
    }

    __aicore__ inline void Process()
    {
        const uint32_t bid = static_cast<uint32_t>(AscendC::GetBlockIdx());
        uint32_t bnum = static_cast<uint32_t>(AscendC::GetBlockNum());
        if (bnum == 0) bnum = 1;

        for (uint32_t b = bid; b < B; b += bnum) {
            LoadQBatch(b);
            AscendC::LocalTensor<float> qBatch = qQueue.DeQue<float>();
            ComputeScores(b, qBatch);
            qQueue.FreeTensor(qBatch);
            ApplyMask(b);
            SoftmaxStable();
            ComputeOut(b);
            StoreOutBatch(b);
        }
    }

private:
    __aicore__ inline uint64_t QOffset(uint32_t b, uint32_t i) const {
        return (static_cast<uint64_t>(b) * I + i) * D;
    }
    __aicore__ inline uint64_t KOffset(uint32_t b, uint32_t j) const {
        return (static_cast<uint64_t>(b) * J + j) * D;
    }
    __aicore__ inline uint64_t VOffset(uint32_t b, uint32_t j) const {
        return (static_cast<uint64_t>(b) * J + j) * D;
    }
    __aicore__ inline uint64_t MOffset(uint32_t b, uint32_t j) const {
        return (static_cast<uint64_t>(b) * 1ULL + 0ULL) * J + j;
    }
    __aicore__ inline uint64_t OOffset(uint32_t b, uint32_t i) const {
        return (static_cast<uint64_t>(b) * I + i) * D;
    }

    __aicore__ inline void LoadQBatch(uint32_t b)
    {
        AscendC::LocalTensor<float> qBatch = qQueue.AllocTensor<float>();
        AscendC::DataCopy(qBatch, qGm[QOffset(b, 0)], I * D);
        qQueue.EnQue(qBatch);
    }

    __aicore__ inline void LoadKRow(uint32_t b, uint32_t j)
    {
        AscendC::LocalTensor<float> kRow = kQueue.AllocTensor<float>();
        AscendC::DataCopy(kRow, kGm[KOffset(b, j)], D);
        kQueue.EnQue(kRow);
    }

    __aicore__ inline void LoadVRow(uint32_t b, uint32_t j)
    {
        AscendC::LocalTensor<float> vRow = vQueue.AllocTensor<float>();
        AscendC::DataCopy(vRow, vGm[VOffset(b, j)], D);
        vQueue.EnQue(vRow);
    }

    __aicore__ inline void ComputeScores(uint32_t b, const AscendC::LocalTensor<float>& qBatch)
    {
        AscendC::LocalTensor<float> scores = bufScores.Get<float>();

        for (uint32_t j = 0; j < J; ++j) {
            LoadKRow(b, j);
            AscendC::LocalTensor<float> kRow = kQueue.DeQue<float>();
            for (uint32_t i = 0; i < I; ++i) {
                float acc = 0.0f;
                const uint32_t qBase = i * D;
                for (uint32_t d = 0; d < D; ++d) {
                    acc += qBatch(qBase + d) * kRow(d);
                }
                scores(i * J + j) = acc;
            }
            kQueue.FreeTensor(kRow);
        }
        AscendC::PipeBarrier<PIPE_V>();
    }

    __aicore__ inline void ApplyMask(uint32_t b)
    {
        AscendC::LocalTensor<float> scores = bufScores.Get<float>();
        AscendC::LocalTensor<uint8_t> maskLocal = maskQueue.AllocTensor<uint8_t>();
        const AscendC::DataCopyExtParams copyParams(1U, 16U, 0U, 0U, 0U);
        const AscendC::DataCopyPadExtParams<uint8_t> padParams(false, 0U, 0U, 0U);
        AscendC::DataCopyPad(maskLocal, mGm[MOffset(b, 0)], copyParams, padParams);
        maskQueue.EnQue(maskLocal);
        maskLocal = maskQueue.DeQue<uint8_t>();
        const float neg = -1.0e20f;

        for (uint32_t j = 0; j < J; ++j) {
            if (maskLocal(j) != 0) {
                for (uint32_t i = 0; i < I; ++i) {
                    scores(i * J + j) = neg;
                }
            }
        }
        maskQueue.FreeTensor(maskLocal);
        AscendC::PipeBarrier<PIPE_V>();
    }

    __aicore__ inline void SoftmaxStable()
    {
        AscendC::LocalTensor<float> scores = bufScores.Get<float>();
        AscendC::LocalTensor<float> probs = bufProbs.Get<float>();

        for (uint32_t i = 0; i < I; ++i) {
            const uint32_t base = i * J;
            float m = scores(base);
            for (uint32_t j = 1; j < J; ++j) {
                const float value = scores(base + j);
                if (value > m) m = value;
            }
            AscendC::Duplicate(probs[base], -m, static_cast<int32_t>(J));
            AscendC::Add(probs[base], scores[base], probs[base], static_cast<int32_t>(J));
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::Exp(probs[base], probs[base], static_cast<int32_t>(J));
            AscendC::PipeBarrier<PIPE_V>();

            float sum = 0.0f;
            for (uint32_t j = 0; j < J; ++j) sum += probs(base + j);
            if (sum == 0.0f) sum = 1.0f;
            const float inv = 1.0f / sum;
            AscendC::Duplicate(scores[base], inv, static_cast<int32_t>(J));
            AscendC::Mul(probs[base], probs[base], scores[base], static_cast<int32_t>(J));
            AscendC::PipeBarrier<PIPE_V>();
        }
    }

    __aicore__ inline void ComputeOut(uint32_t b)
    {
        AscendC::LocalTensor<float> probs = bufProbs.Get<float>();
        AscendC::LocalTensor<float> outBatch = outQueue.AllocTensor<float>();
        AscendC::Duplicate(outBatch, 0.0f, static_cast<int32_t>(I * D));
        AscendC::PipeBarrier<PIPE_V>();

        for (uint32_t j = 0; j < J; ++j) {
            LoadVRow(b, j);
            AscendC::LocalTensor<float> vRow = vQueue.DeQue<float>();
            for (uint32_t i = 0; i < I; ++i) {
                const float p = probs(i * J + j);
                const uint32_t outBase = i * D;
                for (uint32_t d = 0; d < D; ++d) {
                    outBatch(outBase + d) += p * vRow(d);
                }
            }
            vQueue.FreeTensor(vRow);
        }
        AscendC::PipeBarrier<PIPE_V>();
        outQueue.EnQue(outBatch);
    }

    __aicore__ inline void StoreOutBatch(uint32_t b)
    {
        AscendC::LocalTensor<float> outBatch = outQueue.DeQue<float>();
        AscendC::DataCopy(oGm[OOffset(b, 0)], outBatch, I * D);
        outQueue.FreeTensor(outBatch);
    }

private:
    AscendC::TPipe pipe;

    AscendC::TQue<AscendC::TPosition::VECIN, 1> qQueue;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> kQueue;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> vQueue;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> maskQueue;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bufScores;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bufProbs;
    AscendC::TQue<AscendC::TPosition::VECOUT, 1> outQueue;

    AscendC::GlobalTensor<float> qGm, kGm, vGm, oGm;
    AscendC::GlobalTensor<uint8_t> mGm;

    uint32_t B = 0, I = 0, J = 0, D = 0;
    uint32_t totalRows = 0;
};

extern "C" __global__ __aicore__ void halo_attention_custom(
    GM_ADDR q, GM_ADDR k, GM_ADDR v, GM_ADDR mask,
    GM_ADDR out, GM_ADDR workspace, GM_ADDR tiling)
{
    (void)workspace;
    GET_TILING_DATA(t, tiling);
    KernelHaloAttentionCustom op;
    op.Init(q, k, v, mask, out, t.B, t.I, t.J, t.D);
    op.Process();
}

