#include "kernel_operator.h"

static constexpr uint32_t SEQ_LEN = 512;
static constexpr uint32_t HEAD_DIM = 64;
static constexpr uint32_t HALF_WINDOW = 16;
static constexpr uint32_t RING_SLOTS = 33;
static constexpr uint32_t SCORE_ELEMS = 40;

class KernelLocalAttentionCustom {
public:
    __aicore__ inline KernelLocalAttentionCustom() {}

    __aicore__ inline void Init(GM_ADDR q, GM_ADDR k, GM_ADDR v, GM_ADDR out,
                               uint32_t b, uint32_t h, uint32_t s, uint32_t d,
                               uint32_t window_size, uint32_t max_win,
                               uint32_t total_sequences, uint32_t rows_per_task,
                               float scale)
    {
        this->b = b;
        this->h = h;
        this->s = s;
        this->d = d;
        this->windowSize = window_size;
        this->maxWin = max_win;
        this->totalSequences = total_sequences;
        this->rowsPerTask = rows_per_task;
        this->scale = scale;

        const uint64_t total = static_cast<uint64_t>(b) * h * s * d;
        qGm.SetGlobalBuffer((__gm__ float*)q, total);
        kGm.SetGlobalBuffer((__gm__ float*)k, total);
        vGm.SetGlobalBuffer((__gm__ float*)v, total);
        oGm.SetGlobalBuffer((__gm__ float*)out, total);

        pipe.InitBuffer(bufQRow, HEAD_DIM * sizeof(float));
        pipe.InitBuffer(bufKRing, RING_SLOTS * HEAD_DIM * sizeof(float));
        pipe.InitBuffer(bufVRing, RING_SLOTS * HEAD_DIM * sizeof(float));
        pipe.InitBuffer(bufScores, SCORE_ELEMS * sizeof(float));
        pipe.InitBuffer(bufSoftmaxTmp, SCORE_ELEMS * sizeof(float));
        pipe.InitBuffer(bufMulTmp, HEAD_DIM * sizeof(float));
        pipe.InitBuffer(bufOutRow, HEAD_DIM * sizeof(float));

        eventMte2V = pipe.AllocEventID<AscendC::HardEvent::MTE2_V>();
        eventVMte2 = pipe.AllocEventID<AscendC::HardEvent::V_MTE2>();
        eventVS = pipe.AllocEventID<AscendC::HardEvent::V_S>();
        eventSV = pipe.AllocEventID<AscendC::HardEvent::S_V>();
        eventVMte3 = pipe.AllocEventID<AscendC::HardEvent::V_MTE3>();
    }

    __aicore__ inline void Process()
    {
        const uint32_t bid = static_cast<uint32_t>(AscendC::GetBlockIdx());
        if (s != SEQ_LEN || d != HEAD_DIM || windowSize != 32 || maxWin != RING_SLOTS ||
            rowsPerTask != SEQ_LEN || bid >= totalSequences) {
            ReleaseEvents();
            return;
        }

        const uint32_t batch = bid / h;
        const uint32_t head = bid % h;
        for (uint32_t pos = 0; pos <= HALF_WINDOW; ++pos) {
            LoadKWindow(batch, head, pos);
            LoadVWindow(batch, head, pos);
        }

        for (uint32_t qi = 0; qi < rowsPerTask; ++qi) {
            if (qi > 0) {
                const uint32_t newPos = qi + HALF_WINDOW;
                if (newPos < s) {
                    LoadKWindow(batch, head, newPos);
                    LoadVWindow(batch, head, newPos);
                }
            }

            const uint32_t winStart = (qi > HALF_WINDOW) ? (qi - HALF_WINDOW) : 0;
            const uint32_t winEnd = ((qi + HALF_WINDOW + 1) < s) ?
                                    (qi + HALF_WINDOW + 1) : s;
            const uint32_t wLen = winEnd - winStart;

            LoadQRow(batch, head, qi);
            ComputeScoresFromUB(winStart, wLen);
            SoftmaxStableInPlace(wLen);
            ComputeOutFromUB(winStart, wLen);
            StoreOutRow(batch, head, qi);
        }
        ReleaseEvents();
    }

private:
    __aicore__ inline uint64_t Base(uint32_t batch, uint32_t head, uint32_t si) const
    {
        return (static_cast<uint64_t>(batch) * h + head) * (static_cast<uint64_t>(s) * d) +
               static_cast<uint64_t>(si) * d;
    }

    __aicore__ inline void Mte2ToVector()
    {
        AscendC::SetFlag<AscendC::HardEvent::MTE2_V>(static_cast<event_t>(eventMte2V));
        AscendC::WaitFlag<AscendC::HardEvent::MTE2_V>(static_cast<event_t>(eventMte2V));
    }

    __aicore__ inline void VectorToMte2()
    {
        AscendC::SetFlag<AscendC::HardEvent::V_MTE2>(static_cast<event_t>(eventVMte2));
        AscendC::WaitFlag<AscendC::HardEvent::V_MTE2>(static_cast<event_t>(eventVMte2));
    }

    __aicore__ inline void VectorToScalar()
    {
        AscendC::SetFlag<AscendC::HardEvent::V_S>(static_cast<event_t>(eventVS));
        AscendC::WaitFlag<AscendC::HardEvent::V_S>(static_cast<event_t>(eventVS));
    }

    __aicore__ inline void ScalarToVector()
    {
        AscendC::SetFlag<AscendC::HardEvent::S_V>(static_cast<event_t>(eventSV));
        AscendC::WaitFlag<AscendC::HardEvent::S_V>(static_cast<event_t>(eventSV));
    }

    __aicore__ inline void ReleaseEvents()
    {
        pipe.ReleaseEventID<AscendC::HardEvent::MTE2_V>(eventMte2V);
        pipe.ReleaseEventID<AscendC::HardEvent::V_MTE2>(eventVMte2);
        pipe.ReleaseEventID<AscendC::HardEvent::V_S>(eventVS);
        pipe.ReleaseEventID<AscendC::HardEvent::S_V>(eventSV);
        pipe.ReleaseEventID<AscendC::HardEvent::V_MTE3>(eventVMte3);
    }

    __aicore__ inline void LoadQRow(uint32_t batch, uint32_t head, uint32_t qi)
    {
        VectorToMte2();
        AscendC::LocalTensor<float> qRow = bufQRow.Get<float>();
        AscendC::DataCopy(qRow, qGm[Base(batch, head, qi)], HEAD_DIM);
        Mte2ToVector();
    }

    __aicore__ inline void LoadKWindow(uint32_t batch, uint32_t head, uint32_t position)
    {
        VectorToMte2();
        AscendC::LocalTensor<float> kRing = bufKRing.Get<float>();
        const uint32_t slotOffset = (position % RING_SLOTS) * HEAD_DIM;
        AscendC::DataCopy(kRing[slotOffset], kGm[Base(batch, head, position)], HEAD_DIM);
        Mte2ToVector();
    }

    __aicore__ inline void LoadVWindow(uint32_t batch, uint32_t head, uint32_t position)
    {
        VectorToMte2();
        AscendC::LocalTensor<float> vRing = bufVRing.Get<float>();
        const uint32_t slotOffset = (position % RING_SLOTS) * HEAD_DIM;
        AscendC::DataCopy(vRing[slotOffset], vGm[Base(batch, head, position)], HEAD_DIM);
        Mte2ToVector();
    }

    __aicore__ inline void ComputeScoresFromUB(uint32_t winStart, uint32_t wLen)
    {
        AscendC::LocalTensor<float> qRow = bufQRow.Get<float>();
        AscendC::LocalTensor<float> kRing = bufKRing.Get<float>();
        AscendC::LocalTensor<float> scores = bufScores.Get<float>();
        AscendC::LocalTensor<float> mulTmp = bufMulTmp.Get<float>();

        for (uint32_t t = 0; t < wLen; ++t) {
            const uint32_t position = winStart + t;
            const uint32_t slotOffset = (position % RING_SLOTS) * HEAD_DIM;
            AscendC::Mul(mulTmp, qRow, kRing[slotOffset], static_cast<int32_t>(HEAD_DIM));
            VectorToScalar();
            float acc = 0.0f;
            for (uint32_t di = 0; di < HEAD_DIM; ++di) {
                acc += mulTmp(di);
            }
            scores(t) = acc * scale;
        }
    }

    __aicore__ inline void SoftmaxStableInPlace(uint32_t n)
    {
        AscendC::LocalTensor<float> scores = bufScores.Get<float>();
        AscendC::LocalTensor<float> tmp = bufSoftmaxTmp.Get<float>();

        float m = scores(0);
        for (uint32_t i = 1; i < n; ++i) {
            const float value = scores(i);
            if (value > m) m = value;
        }
        ScalarToVector();
        AscendC::Duplicate(tmp, -m, static_cast<int32_t>(n));
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Add(tmp, scores, tmp, static_cast<int32_t>(n));
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Exp(scores, tmp, static_cast<int32_t>(n));
        VectorToScalar();

        float sum = 0.0f;
        for (uint32_t i = 0; i < n; ++i) sum += scores(i);
        const float inv = (sum > 0.0f) ? (1.0f / sum) : 0.0f;
        ScalarToVector();
        AscendC::Duplicate(tmp, inv, static_cast<int32_t>(n));
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Mul(scores, scores, tmp, static_cast<int32_t>(n));
        AscendC::PipeBarrier<PIPE_V>();
    }

    __aicore__ inline void ComputeOutFromUB(uint32_t winStart, uint32_t wLen)
    {
        AscendC::LocalTensor<float> probs = bufScores.Get<float>();
        AscendC::LocalTensor<float> vRing = bufVRing.Get<float>();
        AscendC::LocalTensor<float> mulTmp = bufMulTmp.Get<float>();
        AscendC::LocalTensor<float> outRow = bufOutRow.Get<float>();

        AscendC::Duplicate(outRow, 0.0f, static_cast<int32_t>(HEAD_DIM));
        AscendC::PipeBarrier<PIPE_V>();
        for (uint32_t t = 0; t < wLen; ++t) {
            VectorToScalar();
            const float p = probs(t);
            const uint32_t position = winStart + t;
            const uint32_t slotOffset = (position % RING_SLOTS) * HEAD_DIM;
            ScalarToVector();
            AscendC::Muls(mulTmp, vRing[slotOffset], p, static_cast<int32_t>(HEAD_DIM));
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::Add(outRow, outRow, mulTmp, static_cast<int32_t>(HEAD_DIM));
            AscendC::PipeBarrier<PIPE_V>();
        }
    }

    __aicore__ inline void StoreOutRow(uint32_t batch, uint32_t head, uint32_t qi)
    {
        AscendC::SetFlag<AscendC::HardEvent::V_MTE3>(static_cast<event_t>(eventVMte3));
        AscendC::WaitFlag<AscendC::HardEvent::V_MTE3>(static_cast<event_t>(eventVMte3));
        AscendC::LocalTensor<float> outRow = bufOutRow.Get<float>();
        AscendC::DataCopy(oGm[Base(batch, head, qi)], outRow, HEAD_DIM);
        AscendC::PipeBarrier<PIPE_MTE3>();
    }

private:
    AscendC::TPipe pipe;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bufQRow;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bufKRing;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bufVRing;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bufScores;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bufSoftmaxTmp;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bufMulTmp;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bufOutRow;

    AscendC::GlobalTensor<float> qGm;
    AscendC::GlobalTensor<float> kGm;
    AscendC::GlobalTensor<float> vGm;
    AscendC::GlobalTensor<float> oGm;

    AscendC::TEventID eventMte2V;
    AscendC::TEventID eventVMte2;
    AscendC::TEventID eventVS;
    AscendC::TEventID eventSV;
    AscendC::TEventID eventVMte3;

    uint32_t b = 0, h = 0, s = 0, d = 0;
    uint32_t windowSize = 0, maxWin = 0;
    uint32_t totalSequences = 0, rowsPerTask = 0;
    float scale = 1.0f;
};

extern "C" __global__ __aicore__ void local_attention_custom(
    GM_ADDR q, GM_ADDR k, GM_ADDR v, GM_ADDR out, GM_ADDR workspace, GM_ADDR tiling)
{
    (void)workspace;
    GET_TILING_DATA(tiling_data, tiling);
    KernelLocalAttentionCustom op;
    op.Init(q, k, v, out,
            tiling_data.b, tiling_data.h, tiling_data.s, tiling_data.d,
            tiling_data.window_size, tiling_data.max_win,
            tiling_data.total_sequences, tiling_data.rows_per_task,
            tiling_data.scale);
    op.Process();
}

