#include "kernel_operator.h"

class KernelOutlookAttentionCustom {
public:
    __aicore__ inline KernelOutlookAttentionCustom() {}

    __aicore__ inline void Init(GM_ADDR attn, GM_ADDR v, GM_ADDR y,
                               uint32_t B, uint32_t NH, uint32_t HD, uint32_t C,
                               uint32_t H, uint32_t W, uint32_t HW,
                               uint32_t K, uint32_t P, uint32_t S, uint32_t K2,
                               uint32_t Ho, uint32_t Wo, uint32_t HWo,
                               uint32_t channelElems, uint32_t totalTasks,
                               uint32_t coreNum)
    {
        this->B = B; this->NH = NH; this->HD = HD; this->C = C;
        this->H = H; this->W = W; this->HW = HW;
        this->K = K; this->P = P; this->S = S; this->K2 = K2;
        this->Ho = Ho; this->Wo = Wo; this->HWo = HWo;
        this->channelElems = channelElems;
        this->totalTasks = totalTasks;
        this->coreNum = coreNum;

        const uint64_t aSize = (uint64_t)B * (uint64_t)NH * (uint64_t)HWo * (uint64_t)K2 * (uint64_t)K2;
        const uint64_t vSize = (uint64_t)B * (uint64_t)NH * (uint64_t)HWo * (uint64_t)K2 * (uint64_t)HD;
        const uint64_t ySize = (uint64_t)B * (uint64_t)C * (uint64_t)HW; // [B,C,H,W] contiguous

        aGm.SetGlobalBuffer((__gm__ float*)attn, aSize);
        vGm.SetGlobalBuffer((__gm__ float*)v, vSize);
        yGm.SetGlobalBuffer((__gm__ float*)y, ySize);

        pipe.InitBuffer(wRowQueue, 1, 16 * sizeof(float));
        pipe.InitBuffer(vQueue, 1, this->channelElems * sizeof(float));
        pipe.InitBuffer(weightBuf, this->channelElems * sizeof(float));
        pipe.InitBuffer(productBuf, this->channelElems * sizeof(float));
        pipe.InitBuffer(accBuf, this->channelElems * sizeof(float));
    }

    __aicore__ inline void Process()
    {
        const uint32_t bid = (uint32_t)AscendC::GetBlockIdx();
        for (uint32_t b = bid; b < this->totalTasks; b += this->coreNum) {
            ComputeBCTile(b);
        }
    }

private:
    __aicore__ inline void ComputeBCTile(uint32_t b)
    {
        AscendC::LocalTensor<float> weightPlane = weightBuf.Get<float>();
        AscendC::LocalTensor<float> productPlane = productBuf.Get<float>();
        AscendC::LocalTensor<float> accPlane = accBuf.Get<float>();
        for (uint32_t pix = 0; pix < this->HW; ++pix) {
            uint32_t oh = pix / this->W;
            uint32_t ow = pix - oh * this->W;

            bool firstProduct = true;
            for (uint32_t kh = 0; kh < 3; ++kh) {
                int32_t qh_i = (int32_t)oh - (int32_t)kh + (int32_t)this->P;
                if ((uint32_t)qh_i >= this->Ho) continue;
                uint32_t qh = (uint32_t)qh_i;
                for (uint32_t kw = 0; kw < 3; ++kw) {
                    int32_t qw_i = (int32_t)ow - (int32_t)kw + (int32_t)this->P;
                    if ((uint32_t)qw_i >= this->Wo) continue;
                    uint32_t qw = (uint32_t)qw_i;

                    uint32_t qpos = qh * this->Wo + qw;
                    uint32_t kk_out = kh * 3 + kw;

                    const uint64_t aRow =
                        ((((uint64_t)b * (uint64_t)this->NH + 0ull) * (uint64_t)this->HWo + (uint64_t)qpos) *
                          (uint64_t)this->K2 + (uint64_t)kk_out) * (uint64_t)this->K2;

                    const uint64_t vBase =
                        (((uint64_t)b * (uint64_t)this->NH + 0ull) * (uint64_t)this->HWo + (uint64_t)qpos) *
                        (uint64_t)this->K2 * (uint64_t)this->HD;

                    AscendC::LocalTensor<float> wLocal = wRowQueue.AllocTensor<float>();
                    AscendC::DataCopyExtParams wCopyParams(1, 9 * static_cast<uint32_t>(sizeof(float)), 0, 0, 0);
                    AscendC::DataCopyPadExtParams<float> wPadParams(false, 0, 0, 0.0f);
                    AscendC::DataCopyPad(wLocal, aGm[aRow], wCopyParams, wPadParams);
                    wRowQueue.EnQue(wLocal);
                    wLocal = wRowQueue.DeQue<float>();

                    for (uint32_t kk_in = 0; kk_in < 9; ++kk_in) {
                        const float weight = wLocal.GetValue(kk_in);
                        AscendC::Duplicate(weightPlane, weight, static_cast<int32_t>(this->channelElems));

                        AscendC::LocalTensor<float> vLocal = vQueue.AllocTensor<float>();
                        const uint64_t vOff = vBase + (uint64_t)kk_in * (uint64_t)this->HD;
                        AscendC::DataCopy(vLocal, vGm[vOff], this->channelElems);
                        vQueue.EnQue(vLocal);
                        vLocal = vQueue.DeQue<float>();

                        if (firstProduct) {
                            AscendC::Mul(accPlane, vLocal, weightPlane,
                                         static_cast<int32_t>(this->channelElems));
                            firstProduct = false;
                        } else {
                            AscendC::Mul(productPlane, vLocal, weightPlane,
                                         static_cast<int32_t>(this->channelElems));
                            AscendC::Add(accPlane, accPlane, productPlane,
                                         static_cast<int32_t>(this->channelElems));
                        }
                        vQueue.FreeTensor(vLocal);
                    }
                    wRowQueue.FreeTensor(wLocal);
                }
            }

            AscendC::TEventID eventVS = pipe.FetchEventID<AscendC::HardEvent::V_S>();
            AscendC::SetFlag<AscendC::HardEvent::V_S>(eventVS);
            AscendC::WaitFlag<AscendC::HardEvent::V_S>(eventVS);
            for (uint32_t c = 0; c < this->channelElems; ++c) {
                uint64_t yOff = ((uint64_t)b * (uint64_t)this->C + (uint64_t)c) * (uint64_t)this->HW + (uint64_t)pix;
                yGm.SetValue(yOff, accPlane.GetValue(c));
            }
            pipe.ReleaseEventID<AscendC::HardEvent::V_S>(eventVS);
        }
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::QuePosition::VECIN, 1> wRowQueue;
    AscendC::TQue<AscendC::QuePosition::VECIN, 1> vQueue;
    AscendC::TBuf<AscendC::QuePosition::VECCALC> weightBuf;
    AscendC::TBuf<AscendC::QuePosition::VECCALC> productBuf;
    AscendC::TBuf<AscendC::QuePosition::VECCALC> accBuf;

    AscendC::GlobalTensor<float> aGm;
    AscendC::GlobalTensor<float> vGm;
    AscendC::GlobalTensor<float> yGm;

    uint32_t B, NH, HD, C;
    uint32_t H, W, HW;
    uint32_t K, P, S, K2;
    uint32_t Ho, Wo, HWo;
    uint32_t channelElems, totalTasks, coreNum;
};

extern "C" __global__ __aicore__ void outlook_attention_custom(GM_ADDR attn, GM_ADDR v, GM_ADDR y, GM_ADDR workspace, GM_ADDR tiling)
{
    (void)workspace;
    GET_TILING_DATA(t, tiling);
    KernelOutlookAttentionCustom op;
    op.Init(attn, v, y,
            t.B, t.NH, t.HD, t.C,
            t.H, t.W, t.HW,
            t.K, t.P, t.S, t.K2,
            t.Ho, t.Wo, t.HWo,
            t.channelElems, t.totalTasks,
            t.coreNum);
    op.Process();
}

