    }

    __aicore__ inline uint32_t GetPhysBlock(uint32_t b, uint32_t logicalBlk)
    {
        const uint64_t idx = static_cast<uint64_t>(b) * MBS + logicalBlk;
        return static_cast<uint32_t>(pageTableGm.GetValue(idx));
    }

    __aicore__ inline void LoadQ(const AscendC::LocalTensor<float>& qFP, uint32_t b, uint32_t qpos, uint32_t hq)
    {
        const uint64_t base = QBase(b, qpos, hq);
        for (uint32_t i = 0; i < D; ++i) {
            qFP.SetValue(i, AscendC::ToFloat(qGm.GetValue(base + i)));
        }
    }

    __aicore__ inline void LoadKRow(const AscendC::LocalTensor<float>& kFP, uint32_t phys,
                                   uint32_t off, uint32_t hkv)
    {
        const uint64_t base = (((static_cast<uint64_t>(phys) * PBS + off) * Hkv + hkv) * D);
        for (uint32_t i = 0; i < D; ++i) {
            kFP.SetValue(i, AscendC::ToFloat(kGm.GetValue(base + i)));
        }
    }

    __aicore__ inline void LoadVRow(const AscendC::LocalTensor<float>& vFP, uint32_t phys,
                                   uint32_t off, uint32_t hkv)
    {
        const uint64_t base = (((static_cast<uint64_t>(phys) * PBS + off) * Hkv + hkv) * D);
        for (uint32_t i = 0; i < D; ++i) {
            vFP.SetValue(i, AscendC::ToFloat(vGm.GetValue(base + i)));
        }
    }

    __aicore__ inline float Dot(const AscendC::LocalTensor<float>& a, const AscendC::LocalTensor<float>& b) const
    {
        float acc = 0.0f;
        for (uint32_t i = 0; i < D; ++i) {
            acc += a.GetValue(i) * b.GetValue(i);
        }
        return acc;
    }

    __aicore__ inline void ZeroOut(uint32_t b, uint32_t hq)
    {
        for (uint32_t qpos = 0; qpos < Sq; ++qpos) {
            const uint64_t base = QBase(b, qpos, hq);
            for (uint32_t i = 0; i < D; ++i) {
                outGm.SetValue(base + i, AscendC::ToBfloat16(0.0f));
            }
        }
    }

    __aicore__ inline void ComputeOne(uint32_t b, uint32_t qpos, uint32_t hkv,
                                     uint32_t seqLen, bool causal)
    {
        AscendC::LocalTensor<float> qFP    = bufQ.Get<float>();
        AscendC::LocalTensor<float> kFP    = bufK.Get<float>();
        AscendC::LocalTensor<float> vFP    = bufV.Get<float>();
        AscendC::LocalTensor<float> scores = bufScores.Get<float>();
        AscendC::LocalTensor<float> outFP  = bufOut.Get<float>();
        AscendC::LocalTensor<uint32_t> qPageCache   = bufQ.Get<uint32_t>();
        AscendC::LocalTensor<uint32_t> outPageCache = bufOut.Get<uint32_t>();

        for (uint32_t g = 0; g < 2u; ++g) {
            LoadQ(qFP[g * MAX_D], b, qpos, hkv * 2u + g);
        }
        const uint32_t q_abs = (seqLen >= Sq) ? (seqLen - Sq + qpos) : qpos;
        float maxScore[2] = {-3.402823466e+38f, -3.402823466e+38f}; // -FLT_MAX
        const uint32_t logicalBlocks = (seqLen + PBS - 1u) / PBS;
        for (uint32_t logicalBlk = 0; logicalBlk < logicalBlocks; ++logicalBlk) {
            const uint32_t phys = GetPhysBlock(b, logicalBlk);
            outPageCache.SetValue(logicalBlk, phys);
            const uint32_t pageStart = logicalBlk * PBS;
            uint32_t pageTokens = seqLen - pageStart;
            if (pageTokens > PBS) pageTokens = PBS;
            for (uint32_t off = 0; off < pageTokens; ++off) {
                const uint32_t t = pageStart + off;
                if (causal && (t > q_abs)) {
                    for (uint32_t g = 0; g < 2u; ++g) {
                        scores.SetValue(g * MAX_SEQ + t, -3.402823466e+38f);
                    }
                    continue;
                }
                LoadKRow(kFP, phys, off, hkv);
                for (uint32_t g = 0; g < 2u; ++g) {
                    const float s = Dot(qFP[g * MAX_D], kFP) * scale;
                    scores.SetValue(g * MAX_SEQ + t, s);
                    if (s > maxScore[g]) maxScore[g] = s;
                }
            }
        }
        AscendC::PipeBarrier<PIPE_V>();

        for (uint32_t logicalBlk = 0; logicalBlk < logicalBlocks; ++logicalBlk) {
            qPageCache.SetValue(logicalBlk, outPageCache.GetValue(logicalBlk));
        }
        for (uint32_t g = 0; g < 2u; ++g) {
            const uint32_t scoreBase = g * MAX_SEQ;
            for (uint32_t t = 0; t < seqLen; ++t) {
                const float s = scores.GetValue(scoreBase + t);
                if (s <= -3.0e+38f) {
                    scores.SetValue(scoreBase + t, 0.0f);
                } else {
                    scores.SetValue(scoreBase + t, s - maxScore[g]);
                }
            }
        }
        AscendC::PipeBarrier<PIPE_V>();

        for (uint32_t g = 0; g < 2u; ++g) {
            AscendC::Exp(scores[g * MAX_SEQ], scores[g * MAX_SEQ], static_cast<int32_t>(seqLen));
        }
        AscendC::PipeBarrier<PIPE_V>();

        float invDen[2];
        for (uint32_t g = 0; g < 2u; ++g) {
            float denom = 0.0f;
            for (uint32_t t = 0; t < seqLen; ++t) {
                denom += scores.GetValue(g * MAX_SEQ + t);
            }
            invDen[g] = (denom > 0.0f) ? (1.0f / denom) : 0.0f;
        }

        for (uint32_t g = 0; g < 2u; ++g) {
            for (uint32_t i = 0; i < D; ++i) outFP.SetValue(g * MAX_D + i, 0.0f);
        }

        for (uint32_t logicalBlk = 0; logicalBlk < logicalBlocks; ++logicalBlk) {
            const uint32_t phys = qPageCache.GetValue(logicalBlk);
            const uint32_t pageStart = logicalBlk * PBS;
            uint32_t pageTokens = seqLen - pageStart;
            if (pageTokens > PBS) pageTokens = PBS;
            for (uint32_t off = 0; off < pageTokens; ++off) {
                const uint32_t t = pageStart + off;
                const float w0 = scores.GetValue(t) * invDen[0];
                const float w1 = scores.GetValue(MAX_SEQ + t) * invDen[1];
                if (w0 == 0.0f && w1 == 0.0f) continue;
                LoadVRow(vFP, phys, off, hkv);
                for (uint32_t i = 0; i < D; ++i) {
                    const float v = vFP.GetValue(i);
                    outFP.SetValue(i, outFP.GetValue(i) + w0 * v);
                    outFP.SetValue(MAX_D + i, outFP.GetValue(MAX_D + i) + w1 * v);
                }
            }
        }
        AscendC::PipeBarrier<PIPE_V>();

        for (uint32_t g = 0; g < 2u; ++g) {
            const uint64_t outBase = QBase(b, qpos, hkv * 2u + g);
            for (uint32_t i = 0; i < D; ++i) {
                outGm.SetValue(outBase + i, AscendC::ToBfloat16(outFP.GetValue(g * MAX_D + i)));
            }
        }
        AscendC::PipeBarrier<PIPE_MTE3>();
    }

private:
    AscendC::TPipe pipe;

    AscendC::TBuf<AscendC::TPosition::VECCALC> bufQ;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bufK;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bufV;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bufScores;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bufOut;

    AscendC::GlobalTensor<bfloat16_t> qGm;
    AscendC::GlobalTensor<bfloat16_t> kGm;
    AscendC::GlobalTensor<bfloat16_t> vGm;
    AscendC::GlobalTensor<int32_t>    seqlenGm;
    AscendC::GlobalTensor<int32_t>    pageTableGm;
    AscendC::GlobalTensor<int32_t>    causalFlagGm;
    AscendC::GlobalTensor<bfloat16_t> outGm;

    uint32_t B, Sq, Hq, D, NB, PBS, Hkv, MBS, maxSeq, groups;
    float scale;
};

extern "C" __global__ __aicore__ void paged_attention_kv_cache_custom(
    GM_ADDR q, GM_ADDR k_cache, GM_ADDR v_cache,
    GM_ADDR cache_seqlens, GM_ADDR page_table, GM_ADDR causal_flag,
    GM_ADDR out, GM_ADDR workspace, GM_ADDR tiling)
{
    (void)workspace;
    GET_TILING_DATA(tiling_data, tiling);
    KernelPagedAttentionKVCacheCustom op;
    op.Init(q, k_cache, v_cache,
            cache_seqlens, page_table, causal_flag,
            out,
            tiling_data.B, tiling_data.Sq, tiling_data.Hq, tiling_data.D,
            tiling_data.NB, tiling_data.PBS, tiling_data.Hkv, tiling_data.MBS,
            tiling_data.groups,
            tiling_data.scale);
    op.Process();
}

