#include "kernel_operator.h"

class KernelResidualAttentionCustom {
public:
    __aicore__ inline KernelResidualAttentionCustom() {}

    static constexpr uint32_t MAX_TASK_ROWS = 512;
    static constexpr uint32_t ROW_VALID_ELEMS = 49;
    static constexpr uint32_t ROW_STRIDE_ELEMS = 56;
    static constexpr uint32_t REDUCE_STRIDE_ELEMS = 8;

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR la, GM_ADDR y,
                               uint32_t B, uint32_t C, uint32_t H, uint32_t W,
                               uint32_t HW, uint32_t totalRows, uint32_t rowsPerCore,
                               float invHW)
    {
        ASSERT(AscendC::GetBlockNum() != 0 && "block dim can not be zero!");

        this->HW = HW;
        this->totalRows = totalRows;
        this->rowsPerCore = rowsPerCore;
        this->invHW = invHW;

        uint64_t totalX = static_cast<uint64_t>(B) * static_cast<uint64_t>(C) * static_cast<uint64_t>(HW);
        xGm.SetGlobalBuffer((__gm__ float*)x, totalX);
        yGm.SetGlobalBuffer((__gm__ float*)y, static_cast<uint64_t>(B) * static_cast<uint64_t>(C));
        laGm.SetGlobalBuffer((__gm__ float*)la, 1);

        pipe.InitBuffer(inputQueue, 1, MAX_TASK_ROWS * ROW_STRIDE_ELEMS * sizeof(float));
        pipe.InitBuffer(sumBuf, MAX_TASK_ROWS * REDUCE_STRIDE_ELEMS * sizeof(float));
        pipe.InitBuffer(maxBuf, MAX_TASK_ROWS * REDUCE_STRIDE_ELEMS * sizeof(float));
        pipe.InitBuffer(outputQueue, 1, MAX_TASK_ROWS * sizeof(float));
    }

    __aicore__ inline void Process()
    {
        const uint32_t blk = static_cast<uint32_t>(AscendC::GetBlockIdx());
        const uint32_t startRow = blk * rowsPerCore;
        uint32_t endRow = startRow + rowsPerCore;
        if (endRow > totalRows) endRow = totalRows;
        if (startRow >= endRow) return;

        const float laVal = laGm.GetValue(0);
        const uint32_t taskRows = endRow - startRow;

        AscendC::LocalTensor<float> inputLocal = inputQueue.AllocTensor<float>();
        const uint32_t rowBytes = ROW_VALID_ELEMS * static_cast<uint32_t>(sizeof(float));
        AscendC::DataCopyExtParams inputCopyParams(
            static_cast<uint16_t>(taskRows), rowBytes, 0u, 0u, 0u);
        AscendC::DataCopyPadExtParams<float> inputPadParams(true, 0u, 7u, 0.0f);
        const uint64_t inputOffset = static_cast<uint64_t>(startRow) * static_cast<uint64_t>(HW);
        AscendC::DataCopyPad(inputLocal, xGm[inputOffset], inputCopyParams, inputPadParams);
        inputQueue.EnQue(inputLocal);
        inputLocal = inputQueue.DeQue<float>();

        AscendC::LocalTensor<float> sumLocal = sumBuf.Get<float>();
        AscendC::LocalTensor<float> maxLocal = maxBuf.Get<float>();
        AscendC::LocalTensor<float> outputLocal = outputQueue.AllocTensor<float>();

        for (uint32_t row = 0; row < taskRows; ++row) {
            ComputeOneRowStreamGm(inputLocal, sumLocal, maxLocal, row);
        }

        const AscendC::TEventID vectorToScalar = GetTPipePtr()->FetchEventID(AscendC::HardEvent::V_S);
        AscendC::SetFlag<AscendC::HardEvent::V_S>(vectorToScalar);
        AscendC::WaitFlag<AscendC::HardEvent::V_S>(vectorToScalar);
        for (uint32_t row = 0; row < taskRows; ++row) {
            const float sum = sumLocal.GetValue(row * REDUCE_STRIDE_ELEMS);
            const float mx = maxLocal.GetValue(row * REDUCE_STRIDE_ELEMS);
            outputLocal.SetValue(row, (sum * invHW) + laVal * mx);
        }

        const AscendC::TEventID scalarToMte3 = GetTPipePtr()->FetchEventID(AscendC::HardEvent::S_MTE3);
        AscendC::SetFlag<AscendC::HardEvent::S_MTE3>(scalarToMte3);
        AscendC::WaitFlag<AscendC::HardEvent::S_MTE3>(scalarToMte3);
        outputQueue.EnQue(outputLocal);
        outputLocal = outputQueue.DeQue<float>();

        if ((taskRows & 7u) == 0u) {
            AscendC::DataCopy(yGm[startRow], outputLocal, taskRows);
        } else {
            const uint32_t outputBytes = taskRows * static_cast<uint32_t>(sizeof(float));
            AscendC::DataCopyExtParams outputCopyParams(1u, outputBytes, 0u, 0u, 0u);
            AscendC::DataCopyPad(yGm[startRow], outputLocal, outputCopyParams);
        }

        outputQueue.FreeTensor(outputLocal);
        inputQueue.FreeTensor(inputLocal);
    }

private:
    __aicore__ inline void ComputeOneRowStreamGm(const AscendC::LocalTensor<float>& inputLocal,
                                                 const AscendC::LocalTensor<float>& sumLocal,
                                                 const AscendC::LocalTensor<float>& maxLocal,
                                                 uint32_t row)
    {
        const uint32_t inputOffset = row * ROW_STRIDE_ELEMS;
        const uint32_t reduceOffset = row * REDUCE_STRIDE_ELEMS;
        AscendC::WholeReduceSum(sumLocal[reduceOffset], inputLocal[inputOffset],
                               static_cast<int32_t>(ROW_VALID_ELEMS), 1, 1, 1, 7);
        AscendC::WholeReduceMax(maxLocal[reduceOffset], inputLocal[inputOffset],
                               static_cast<int32_t>(ROW_VALID_ELEMS), 1, 1, 1, 7);
    }

private:
    AscendC::GlobalTensor<float> xGm;
    AscendC::GlobalTensor<float> laGm;
    AscendC::GlobalTensor<float> yGm;
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> inputQueue;
    AscendC::TQue<AscendC::TPosition::VECOUT, 1> outputQueue;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf;
    AscendC::TBuf<AscendC::TPosition::VECCALC> maxBuf;

    uint32_t HW;
    uint32_t totalRows, rowsPerCore;
    float invHW;
};

extern "C" __global__ __aicore__ void residual_attention_custom(GM_ADDR x, GM_ADDR la, GM_ADDR y, GM_ADDR workspace, GM_ADDR tiling)
{
    GET_TILING_DATA(tiling_data, tiling);
    KernelResidualAttentionCustom op;
    op.Init(x, la, y,
            tiling_data.B, tiling_data.C, tiling_data.H, tiling_data.W,
            tiling_data.HW, tiling_data.totalRows, tiling_data.rowsPerCore,
            tiling_data.invHW);
    op.Process();
}

