#include "kernel_operator.h"
#include <cstdint>

class KernelS2Attention {
public:
    __aicore__ inline KernelS2Attention() {}

    __aicore__ inline void Init(GM_ADDR attn, GM_ADDR x_all, GM_ADDR y,
                               uint32_t B, uint32_t K, uint32_t H, uint32_t W, uint32_t C,
                               uint32_t HW, uint32_t batchTasks, uint32_t spatialRows,
                               uint32_t channelTile)
    {
        this->B = B;
        this->K = K; // 3
        this->H = H;
        this->W = W;
        this->C = C;
        this->HW = HW;
        this->batchTasks = batchTasks;
        this->spatialRows = spatialRows;
        this->channelTile = channelTile;

        const uint64_t attnSize = (uint64_t)B * (uint64_t)K * (uint64_t)C; // [B,3,C]
        const uint64_t xSize    = (uint64_t)B * (uint64_t)K * (uint64_t)HW * (uint64_t)C; // [B,3,HW,C]
        const uint64_t ySize    = (uint64_t)B * (uint64_t)HW * (uint64_t)C; // [B,HW,C]

        attnGm.SetGlobalBuffer((__gm__ float*)attn, attnSize);
        xGm.SetGlobalBuffer((__gm__ float*)x_all, xSize);
        yGm.SetGlobalBuffer((__gm__ float*)y, ySize);

        const uint32_t channelBytes = this->channelTile * static_cast<uint32_t>(sizeof(float));
        pipe.InitBuffer(attnQueue, 1, 3U * channelBytes);
        pipe.InitBuffer(xQueue, 1, 3U * channelBytes);
        pipe.InitBuffer(yQueue, 1, channelBytes);
    }

    __aicore__ inline void Process()
    {
        const uint32_t coreId  = (uint32_t)AscendC::GetBlockIdx();
        const uint32_t coreNum = (uint32_t)AscendC::GetBlockNum();
        if (coreNum == 0) return;

        for (uint32_t b = coreId; b < this->batchTasks; b += coreNum) {
            AscendC::LocalTensor<float> attnLocal = attnQueue.AllocTensor<float>();
            AscendC::DataCopy(attnLocal, attnGm[(uint32_t)AttnBase(b)], 3U * this->channelTile);
            attnQueue.EnQue(attnLocal);
            attnLocal = attnQueue.DeQue<float>();

            for (uint32_t hw = 0; hw < this->spatialRows; ++hw) {
                ComputeRow(b, hw, attnLocal);
            }

            attnQueue.FreeTensor(attnLocal);
        }
    }

private:
    __aicore__ inline uint64_t AttnBase(uint32_t b) const
    {
        return (uint64_t)b * (uint64_t)this->K * (uint64_t)this->C;
    }

    __aicore__ inline uint64_t XBase(uint32_t b, uint32_t k, uint32_t hw) const
    {
        return (((uint64_t)b * (uint64_t)this->K + (uint64_t)k) * (uint64_t)this->HW + (uint64_t)hw) * (uint64_t)this->C;
    }

    __aicore__ inline uint64_t YBase(uint32_t b, uint32_t hw) const
    {
        return ((uint64_t)b * (uint64_t)this->HW + (uint64_t)hw) * (uint64_t)this->C;
    }

    __aicore__ inline void ComputeRow(uint32_t b, uint32_t hw,
                                     const AscendC::LocalTensor<float>& attnLocal)
    {
        const uint64_t xB0   = XBase(b, 0, hw);
        const uint64_t xB1   = XBase(b, 1, hw);
        const uint64_t xB2   = XBase(b, 2, hw);
        const uint64_t yB    = YBase(b, hw);

        AscendC::LocalTensor<float> xLocal = xQueue.AllocTensor<float>();
        AscendC::DataCopy(xLocal, xGm[(uint32_t)xB0], this->channelTile);
        AscendC::DataCopy(xLocal[this->channelTile], xGm[(uint32_t)xB1], this->channelTile);
        AscendC::DataCopy(xLocal[2U * this->channelTile], xGm[(uint32_t)xB2], this->channelTile);
        xQueue.EnQue(xLocal);
        xLocal = xQueue.DeQue<float>();

        AscendC::LocalTensor<float> yLocal = yQueue.AllocTensor<float>();
        AscendC::Mul(xLocal, xLocal, attnLocal, (int32_t)this->channelTile);
        AscendC::Mul(xLocal[this->channelTile], xLocal[this->channelTile],
                     attnLocal[this->channelTile], (int32_t)this->channelTile);
        AscendC::Mul(xLocal[2U * this->channelTile], xLocal[2U * this->channelTile],
                     attnLocal[2U * this->channelTile], (int32_t)this->channelTile);
        AscendC::Add(yLocal, xLocal, xLocal[this->channelTile], (int32_t)this->channelTile);
        AscendC::Add(yLocal, yLocal, xLocal[2U * this->channelTile], (int32_t)this->channelTile);
        yQueue.EnQue(yLocal);
        xQueue.FreeTensor(xLocal);

        yLocal = yQueue.DeQue<float>();
        AscendC::DataCopy(yGm[(uint32_t)yB], yLocal, this->channelTile);
        yQueue.FreeTensor(yLocal);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> attnQueue;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> xQueue;
    AscendC::TQue<AscendC::TPosition::VECOUT, 1> yQueue;

    AscendC::GlobalTensor<float> attnGm;
    AscendC::GlobalTensor<float> xGm;
    AscendC::GlobalTensor<float> yGm;

    uint32_t B{0}, K{0}, H{0}, W{0}, C{0};
    uint32_t HW{0}, batchTasks{0}, spatialRows{0};
    uint32_t channelTile{0};
};

extern "C" __global__ __aicore__ void s2_attention_custom(GM_ADDR attn,
                                                         GM_ADDR x_all,
                                                         GM_ADDR y,
                                                         GM_ADDR workspace,
                                                         GM_ADDR tiling)
{
    (void)workspace;
    GET_TILING_DATA(tiling_data, tiling);
    KernelS2Attention op;
    op.Init(attn, x_all, y,
            tiling_data.B, tiling_data.K, tiling_data.H, tiling_data.W, tiling_data.C,
            tiling_data.HW, tiling_data.batchTasks, tiling_data.spatialRows,
            tiling_data.channelTile);
    op.Process();
}

