#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;

class KernelSKAttention {
public:
    __aicore__ inline KernelSKAttention() {}

    __aicore__ inline void Init(GM_ADDR attn, GM_ADDR feats, GM_ADDR y,
                               uint32_t K, uint32_t bs, uint32_t C,
                               uint32_t H, uint32_t W, uint32_t hw,
                               uint32_t totalOut, uint32_t rowCount,
                               uint32_t coreNum, uint32_t batchRows,
                               uint32_t storageStride)
    {
        ASSERT(AscendC::GetBlockNum() != 0 && "block dim can not be zero!");
        this->K = K;
        this->bs = bs;
        this->C = C;
        this->H = H;
        this->W = W;
        this->hw = hw;
        this->totalOut = totalOut;
        this->rowCount = rowCount;
        this->batchRows = batchRows;
        this->storageStride = storageStride;

        const uint32_t bid = static_cast<uint32_t>(AscendC::GetBlockIdx());
        const uint32_t bnum = coreNum;
        this->coreRowStart = static_cast<uint32_t>(
            (static_cast<uint64_t>(bid) * rowCount) / bnum);
        this->coreRowEnd = static_cast<uint32_t>(
            (static_cast<uint64_t>(bid + 1U) * rowCount) / bnum);

        const uint64_t attnSize = static_cast<uint64_t>(K) * rowCount;
        const uint64_t featsSize = static_cast<uint64_t>(K) * totalOut;
        attnGm.SetGlobalBuffer((__gm__ float*)attn, attnSize);
        featsGm.SetGlobalBuffer((__gm__ float*)feats, featsSize);
        yGm.SetGlobalBuffer((__gm__ float*)y, totalOut);

        pipe.InitBuffer(qFeats, BUFFER_NUM, batchRows * hw * sizeof(float));
        pipe.InitBuffer(qAttn, BUFFER_NUM, batchRows * sizeof(float));
        pipe.InitBuffer(qOut, BUFFER_NUM, batchRows * storageStride * sizeof(float));
        pipe.InitBuffer(offsetBuf, storageStride * sizeof(uint32_t));
        pipe.InitBuffer(featsBuf, storageStride * sizeof(float));
        pipe.InitBuffer(weightBuf, storageStride * sizeof(float));
    }

    __aicore__ inline void Process()
    {
        for (uint32_t row = this->coreRowStart; row < this->coreRowEnd; row += this->batchRows) {
            uint32_t validRows = this->coreRowEnd - row;
            if (validRows > this->batchRows) validRows = this->batchRows;
            ComputeTile(row, validRows);
            CopyOut(row, validRows);
        }
    }

private:
    __aicore__ inline void CopyInput(AscendC::LocalTensor<float>& dst,
                                     const AscendC::GlobalTensor<float>& src,
                                     uint64_t offset, uint32_t elems)
    {
        if ((elems & 7U) == 0U) {
            AscendC::DataCopy(dst, src[offset], elems);
        } else {
            AscendC::DataCopyExtParams params(1U, elems * static_cast<uint32_t>(sizeof(float)), 0U, 0U, 0U);
            AscendC::DataCopyPadExtParams<float> padParams(false, 0U, 0U, 0.0f);
            AscendC::DataCopyPad(dst, src[offset], params, padParams);
        }
    }

    __aicore__ inline void ComputeTile(uint32_t rowStart, uint32_t validRows)
    {
        AscendC::LocalTensor<float> outLocal = qOut.AllocTensor<float>();
        AscendC::Duplicate(outLocal, 0.0f,
                           static_cast<int32_t>(validRows * this->storageStride));

        AscendC::LocalTensor<uint32_t> offsets = offsetBuf.Get<uint32_t>();
        AscendC::LocalTensor<float> featsPlane = featsBuf.Get<float>();
        AscendC::LocalTensor<float> weightPlane = weightBuf.Get<float>();

        for (uint32_t k = 0; k < this->K; ++k) {
            AscendC::LocalTensor<float> featsLocal = qFeats.AllocTensor<float>();
            const uint64_t featsOffset = static_cast<uint64_t>(k) * this->totalOut +
                                         static_cast<uint64_t>(rowStart) * this->hw;
            CopyInput(featsLocal, featsGm, featsOffset, validRows * this->hw);
            qFeats.EnQue(featsLocal);

            AscendC::LocalTensor<float> attnLocal = qAttn.AllocTensor<float>();
            const uint64_t attnOffset = static_cast<uint64_t>(k) * this->rowCount + rowStart;
            CopyInput(attnLocal, attnGm, attnOffset, validRows);
            qAttn.EnQue(attnLocal);

            featsLocal = qFeats.DeQue<float>();
            attnLocal = qAttn.DeQue<float>();
            for (uint32_t r = 0; r < validRows; ++r) {
                AscendC::ArithProgression<int32_t>(offsets.ReinterpretCast<int32_t>(),
                                                   static_cast<int32_t>(r * this->hw * sizeof(float)),
                                                   static_cast<int32_t>(sizeof(float)),
                                                   static_cast<int32_t>(this->hw));
                AscendC::Gather(featsPlane, featsLocal, offsets, 0U, this->hw);
                const float weight = attnLocal.GetValue(r);
                AscendC::Duplicate(weightPlane, weight, static_cast<int32_t>(this->hw));
                AscendC::Mul(featsPlane, featsPlane, weightPlane, static_cast<int32_t>(this->hw));
                AscendC::LocalTensor<float> accum = outLocal[r * this->storageStride];
                AscendC::Add(accum, accum, featsPlane, static_cast<int32_t>(this->hw));
            }
            qAttn.FreeTensor(attnLocal);
            qFeats.FreeTensor(featsLocal);
        }
        qOut.EnQue(outLocal);
    }

    __aicore__ inline void CopyOut(uint32_t rowStart, uint32_t validRows)
    {
        AscendC::LocalTensor<float> outLocal = qOut.DeQue<float>();
        AscendC::DataCopyExtParams params(static_cast<uint16_t>(validRows),
            this->hw * static_cast<uint32_t>(sizeof(float)), 0U, 0U, 0U);
        AscendC::DataCopyPad(yGm[static_cast<uint64_t>(rowStart) * this->hw], outLocal, params);
        qOut.FreeTensor(outLocal);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::QuePosition::VECIN, BUFFER_NUM> qFeats;
    AscendC::TQue<AscendC::QuePosition::VECIN, BUFFER_NUM> qAttn;
    AscendC::TQue<AscendC::QuePosition::VECOUT, BUFFER_NUM> qOut;
    AscendC::TBuf<AscendC::QuePosition::VECCALC> offsetBuf;
    AscendC::TBuf<AscendC::QuePosition::VECCALC> featsBuf;
    AscendC::TBuf<AscendC::QuePosition::VECCALC> weightBuf;
    AscendC::GlobalTensor<float> attnGm;
    AscendC::GlobalTensor<float> featsGm;
    AscendC::GlobalTensor<float> yGm;
    uint32_t K, bs, C, H, W, hw, totalOut, rowCount;
    uint32_t coreRowStart, coreRowEnd, batchRows, storageStride;
};

extern "C" __global__ __aicore__ void sk_attention_custom(GM_ADDR attn, GM_ADDR feats, GM_ADDR y,
                                                            GM_ADDR workspace, GM_ADDR tiling)
{
    GET_TILING_DATA(tiling_data, tiling);
    KernelSKAttention op;
    op.Init(attn, feats, y, tiling_data.K, tiling_data.bs, tiling_data.C,
            tiling_data.H, tiling_data.W, tiling_data.hw, tiling_data.totalOut,
            tiling_data.rowCount, tiling_data.coreNum, tiling_data.batchRows,
            tiling_data.storageStride);
    op.Process();
}

