#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;

class KernelSequentialPolarizedSelfAttentionCustom {
public:
    __aicore__ inline KernelSequentialPolarizedSelfAttentionCustom() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR channel_weight, GM_ADDR spatial_weight, GM_ADDR y,
                               uint32_t B, uint32_t C, uint32_t H, uint32_t W, uint32_t HW,
                               uint32_t usedCores, uint32_t rowStride, uint32_t channelChunk)
    {
        (void)H; (void)W;
        this->B = B;
        this->C = C;
        this->HW = HW;
        this->usedCores = usedCores;
        this->rowStride = rowStride;
        this->channelChunk = channelChunk;
        this->coreIdx = static_cast<uint32_t>(AscendC::GetBlockIdx());

        xGm.SetGlobalBuffer((__gm__ float*)x, (uint64_t)B * (uint64_t)C * (uint64_t)HW);
        yGm.SetGlobalBuffer((__gm__ float*)y, (uint64_t)B * (uint64_t)C * (uint64_t)HW);
        cwGm.SetGlobalBuffer((__gm__ float*)channel_weight, (uint64_t)B * (uint64_t)C);
        swGm.SetGlobalBuffer((__gm__ float*)spatial_weight, (uint64_t)B * (uint64_t)HW);

        pipe.InitBuffer(xQueue, BUFFER_NUM, this->channelChunk * this->rowStride * sizeof(float));
        pipe.InitBuffer(yQueue, BUFFER_NUM, this->channelChunk * this->rowStride * sizeof(float));
        pipe.InitBuffer(cwQueue, BUFFER_NUM, this->channelChunk * sizeof(float));
        pipe.InitBuffer(swQueue, BUFFER_NUM, this->rowStride * sizeof(float));
        pipe.InitBuffer(gateBuf, this->rowStride * sizeof(float));
    }

    __aicore__ inline void Process()
    {
        if (coreIdx >= usedCores) return;

        const uint32_t rowBytes = HW * static_cast<uint32_t>(sizeof(float));
        const uint8_t rightPadding = static_cast<uint8_t>(rowStride - HW);
        const AscendC::DataCopyPadExtParams<float> padParams{true, 0, rightPadding, 0.0f};

        for (uint32_t b = coreIdx; b < B; b += usedCores) {
            AscendC::LocalTensor<float> swLocal = swQueue.AllocTensor<float>();
            const AscendC::DataCopyExtParams swCopy{1, rowBytes, 0, 0, 0};
            AscendC::DataCopyPad(swLocal, swGm[static_cast<uint64_t>(b) * HW], swCopy, padParams);
            swQueue.EnQue(swLocal);
            swLocal = swQueue.DeQue<float>();

            for (uint32_t c0 = 0; c0 < C; c0 += channelChunk) {
                const uint32_t channelCount = (c0 + channelChunk <= C) ? channelChunk : (C - c0);
                const uint64_t rowBase = (static_cast<uint64_t>(b) * C + c0) * HW;

                AscendC::LocalTensor<float> cwLocal = cwQueue.AllocTensor<float>();
                AscendC::DataCopy(cwLocal, cwGm[static_cast<uint64_t>(b) * C + c0], channelCount);
                cwQueue.EnQue(cwLocal);

                AscendC::LocalTensor<float> xLocal = xQueue.AllocTensor<float>();
                const AscendC::DataCopyExtParams xCopy{
                    static_cast<uint16_t>(channelCount), rowBytes, 0, 0, 0};
                AscendC::DataCopyPad(xLocal, xGm[rowBase], xCopy, padParams);
                xQueue.EnQue(xLocal);

                cwLocal = cwQueue.DeQue<float>();
                xLocal = xQueue.DeQue<float>();
                AscendC::LocalTensor<float> yLocal = yQueue.AllocTensor<float>();
                AscendC::LocalTensor<float> gateLocal = gateBuf.Get<float>();

                for (uint32_t c = 0; c < channelCount; ++c) {
                    const uint32_t rowOffset = c * rowStride;
                    AscendC::Duplicate(gateLocal, cwLocal.GetValue(c), HW);
                    AscendC::Mul(gateLocal, gateLocal, swLocal, HW);
                    AscendC::Mul(yLocal[rowOffset], xLocal[rowOffset], gateLocal, HW);
                }

                xQueue.FreeTensor(xLocal);
                cwQueue.FreeTensor(cwLocal);
                yQueue.EnQue(yLocal);
                yLocal = yQueue.DeQue<float>();
                const AscendC::DataCopyExtParams yCopy{
                    static_cast<uint16_t>(channelCount), rowBytes, 0, 0, 0};
                AscendC::DataCopyPad(yGm[rowBase], yLocal, yCopy);
                yQueue.FreeTensor(yLocal);
            }
            swQueue.FreeTensor(swLocal);
        }
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xQueue;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yQueue;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> cwQueue;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> swQueue;
    AscendC::TBuf<AscendC::TPosition::VECCALC> gateBuf;

    AscendC::GlobalTensor<float> xGm;
    AscendC::GlobalTensor<float> cwGm;
    AscendC::GlobalTensor<float> swGm;
    AscendC::GlobalTensor<float> yGm;

    uint32_t B = 0, C = 0, HW = 0;
    uint32_t usedCores = 0;
    uint32_t rowStride = 0;
    uint32_t channelChunk = 0;
    uint32_t coreIdx = 0;
};

extern "C" __global__ __aicore__ void sequential_polarized_self_attention_custom(
    GM_ADDR x, GM_ADDR channel_weight, GM_ADDR spatial_weight, GM_ADDR y, GM_ADDR workspace, GM_ADDR tiling)
{
    (void)workspace;
    GET_TILING_DATA(tiling_data, tiling);
    KernelSequentialPolarizedSelfAttentionCustom op;
    op.Init(x, channel_weight, spatial_weight, y,
            tiling_data.B, tiling_data.C, tiling_data.H, tiling_data.W, tiling_data.HW,
            tiling_data.usedCores, tiling_data.rowStride, tiling_data.channelChunk);
    op.Process();
}

