        yLocal = yQueue.DeQue<float>();
        AscendC::DataCopyExtParams copyOutParams {
            static_cast<uint16_t>(this->Cg), rowBytes, 0u, 0u, 0u
        };
        AscendC::DataCopyPad(yGm[groupBase], yLocal, copyOutParams);
        yQueue.FreeTensor(yLocal);
        xQueue.FreeTensor(xLocal);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TBuf<> gateBuf;
    AscendC::TBuf<> tmpBuf;
    AscendC::TBuf<> redBuf;
    AscendC::TBuf<> sigTmpBuf;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xQueue;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yQueue;

    AscendC::GlobalTensor<float> xGm;
    AscendC::GlobalTensor<float> yGm;
    AscendC::GlobalTensor<float> wGm;
    AscendC::GlobalTensor<float> bGm;

    uint32_t B, C, H, W;
    uint32_t G, Cg, HW, groupsTotal;
    uint32_t hwAlign;
    float invHW;
    float invCg;
    float epsilon;
    uint32_t sigTmpBytes;
